import{r as e}from"./react-SIfiwpqq.js";var t=e({blog:()=>a,default:()=>c,learn:()=>i,music:()=>s,poses:()=>n,progressions:()=>o,routines:()=>r}),n=JSON.parse(`{"wrist-circles":{"name":"Wrist Circles","description":"Stand tall with elbows soft and forearms in front of you. Draw slow circles with both wrists, four counts one way and four the other, keeping the fingers loose.","goodFor":"Warms the wrists and forearms that do most of the work in every prop.","alignmentCues":["Elbows stay still; only the wrists move.","Keep the circles big and smooth."],"commonMistakes":["Rushing the circles so they turn into flicks."]},"arm-circles":{"name":"Arm Circles","description":"Feet hip-width apart, arms long. Swing both arms in big forward circles for four counts, then backward for four, letting the shoulder blades glide.","goodFor":"Opens the shoulders for staff spins and hoop work overhead.","alignmentCues":["Ribs stay down as the arms pass overhead.","Breathe out on the downswing."]},"shoulder-rolls":{"name":"Shoulder Rolls","description":"Arms relaxed by your sides. Lift the shoulders to the ears, roll them back and down, and repeat in a slow loop.","goodFor":"Releases tension that makes throws stiff and short."},"neck-rolls":{"name":"Neck Half Circles","description":"Drop the chin towards the chest and sweep it slowly from shoulder to shoulder in a half circle. Keep the head from tipping back.","goodFor":"Eases the neck before looking up at throws for long periods.","avoidIf":["Neck injury or dizziness when moving the head."]},"hip-circles":{"name":"Hip Circles","description":"Hands on hips, knees soft. Circle the hips slowly one way for two bars and the other way for two, keeping the head level.","goodFor":"Prepares the hips for waist hooping and the body for flow."},"torso-twists":{"name":"Torso Twists","description":"Feet wide, arms loose. Turn the ribs left and right and let the arms swing and wrap around you like empty sleeves.","goodFor":"Wakes up rotation for staff weaves and hoop passes."},"knee-bounce":{"name":"Knee Bounce","description":"Stand with feet under the hips and bounce gently through the knees on every beat, arms swinging loosely. Find the music in your legs.","goodFor":"Puts the beat into your body before you pick up a prop."},"one-ball-toss":{"name":"One-Ball Toss","description":"Hold one ball in your right hand at waist height. Scoop it in, then toss it in an arc that peaks just above eye level and drops into the left hand. Toss it back the same way. Keep your eyes on the top of the arc, not your hands.","goodFor":"Builds the arc every juggling pattern is made from.","alignmentCues":["Elbows by your sides, forearms level.","The peak is the same height every throw.","Catch at waist height and let the hand give a little."],"commonMistakes":["Throwing forward so you have to step after the ball.","Watching the hands instead of the peak."]},"two-ball-exchange":{"name":"Two-Ball Exchange","description":"One ball in each hand. Toss the right ball in its arc; when it peaks, toss the left ball underneath it on the inside. Catch both and pause. Then start with the left hand.","goodFor":"Teaches the exchange: the second throw goes as the first one peaks.","alignmentCues":["Second throw on the peak, never early.","Throw the second ball inside the first."],"commonMistakes":["Passing the second ball across instead of throwing it.","Throwing both at once."]},"cascade":{"name":"Three-Ball Cascade","description":"Two balls in the right hand, one in the left. Throw from the right; as it peaks throw from the left; as that peaks throw from the right again. Every throw goes on the beat, crossing to the other hand in a figure-8 arc.","goodFor":"The foundation pattern of juggling.","modifications":["Practise the flash: three throws, three catches, stop."],"deepen":["Juggle to a faster tempo with lower peaks.","Count 20 catches without a drop."],"alignmentCues":["Throw from the inside, catch on the outside.","Peaks level, at eye height.","Stand against a wall if you keep walking forward."],"commonMistakes":["Throwing forward and chasing the pattern.","Rushing as soon as one throw goes wrong."]},"reverse-cascade":{"name":"Reverse Cascade","description":"The cascade turned inside out: every ball is thrown from the outside, over the top of the pattern, and dropped down the middle into the other hand.","goodFor":"Trains throws from the outside and opens up tricks like the Mills Mess.","alignmentCues":["Throws loop over the incoming ball.","Catch in the centre."]},"siteswap-423":{"name":"423","description":"A three-ball pattern: a high self-throw (4), a held ball (2), then a cascade throw (3). The 4 goes up the same side; the 2 is simply held for a beat.","goodFor":"Your first siteswap trick: teaches high throws and holds."},"siteswap-441":{"name":"441","description":"Two high throws that stay on their own side (4, 4) followed by a quick zip across (1) from hand to hand.","goodFor":"Builds timing between high throws and fast passes."},"two-in-one":{"name":"Two in One Hand","description":"Juggle two balls in one hand in side-by-side columns or small outward circles, one throw on every other beat. Practise each hand.","goodFor":"The building block of four-ball juggling."},"siteswap-531":{"name":"531","description":"A very high crossing throw (5), a cascade throw (3) and a quick zip (1). The 5 goes up while the other two balls keep working underneath.","goodFor":"Height control and a showpiece three-ball trick."},"shower":{"name":"Three-Ball Shower","description":"Balls travel in a circle: the right hand throws every ball high over to the left, and the left hand passes each one straight back to the right.","goodFor":"Classic circular pattern; trains fast hand-to-hand passes."},"mills-mess":{"name":"Mills Mess","description":"A three-ball cascade where the arms keep crossing and uncrossing, so each throw comes from the opposite side of the body. The ball paths trace a weaving pattern.","goodFor":"A famous crowd-pleaser that sharpens coordination."},"four-ball-fountain":{"name":"Four-Ball Fountain","description":"Each hand juggles two balls in its own column, the hands alternating throws so the pattern never crosses.","goodFor":"Your first four-ball pattern."},"sync-fountain":{"name":"Synchronous Fountain","description":"Four balls with both hands throwing at exactly the same moment, each to its own side.","goodFor":"Builds symmetry and leads to sync tricks."},"five-ball-cascade":{"name":"Five-Ball Cascade","description":"The cascade with five balls: high, fast throws in a tall crossing pattern. Expect months of practice.","goodFor":"A milestone for dedicated jugglers."},"tennis":{"name":"Tennis","description":"A cascade where one ball, the \\"tennis ball\\", always travels over the top of the pattern instead of through the middle. Whichever hand holds it throws it on the outside so it lobs across the top like a rally over a net.","goodFor":"First step into outside throws while the timing stays a plain cascade.","alignmentCues":["Keep one ball in view as the tennis ball.","Throw it from the outside, same height as the rest."],"commonMistakes":["Losing track of which ball goes over.","Throwing the over ball higher than the others."]},"half-shower":{"name":"Half Shower","description":"One hand throws every ball over the top while the other throws every ball underneath. The two arcs separate into a high outside path and a low inside path, and the balls chase each other round in a loop.","goodFor":"Splitting the hands into two roles while the rhythm stays even.","alignmentCues":["Over hand throws outside and a touch higher.","Under hand keeps its throws tight and inside."],"commonMistakes":["Both hands drifting back to plain cascade throws.","Collisions in the middle when the arcs are the same height."]},"claw-cascade":{"name":"Claw Cascade","description":"The cascade caught palm down. Each hand reaches up and grabs the ball out of the air from above, then pulls down and turns over to throw. The hands look like they are pawing at the balls.","goodFor":"Builds active grabbing catches and a strong wrist turn.","alignmentCues":["Reach up to meet the ball, fingers spread.","Pull down and flip the wrist in one move."],"commonMistakes":["Grabbing late so the ball hits the back of the hand.","Throwing low because the turn takes too long."]},"chops":{"name":"Chops","description":"After each catch the hand carries the ball high across the body and chops down, throwing from the far side. The arms swing past each other like slicing, and the balls fall into a tight cascade underneath.","goodFor":"Big arm carries with the cascade timing still underneath.","alignmentCues":["Catch high, carry across, chop down and throw.","Throw from the opposite side of your body."],"commonMistakes":["Carrying too far so the next catch is late.","Arms clashing in the middle."]},"penguin-cascade":{"name":"Penguin Cascade","description":"Arms hang straight at your sides with the palms turned down. Every catch happens low and out to the side, and the throws flick up from the hip. You look like a penguin flapping to the beat.","goodFor":"Wrist-driven throws and catches far from the usual hand position.","alignmentCues":["Elbows straight, hands by the hips.","Flick from the wrist, palms facing back."],"commonMistakes":["Bending the elbows back into a normal cascade.","Throws drifting forward because the wrist is cocked."]},"under-the-leg":{"name":"Under the Leg","description":"A cascade where every sixth throw goes under the right leg. Lift the knee as the ball arrives, reach under the thigh and throw up from the outside, then put the foot down for the next catch.","goodFor":"The first body throw: leg lift and arm reach timed to a single beat.","alignmentCues":["Lift the knee before the throw, not during it.","Throw a little higher to cover the extra reach."],"commonMistakes":["Bending forward to the leg instead of lifting the knee.","Rushing the next throw after the leg goes down."]},"behind-the-back":{"name":"Behind the Back","description":"Every sixth throw, the right hand swings behind the waist and throws the ball up over the opposite shoulder, landing it back in the pattern in front. The other throws stay a normal cascade.","goodFor":"Throwing blind into a pattern you cannot see.","alignmentCues":["Swing the hand behind early, as the ball lands.","Aim over the far shoulder, a little higher than normal."],"commonMistakes":["Throwing too far forward so the ball lands in front of you.","Twisting the whole torso."]},"over-the-shoulder":{"name":"Over the Shoulder","description":"Every sixth throw, the right hand sends its ball high from the front, up and back over the left shoulder. The left hand swings round behind its hip and catches it blind, then flicks its next ball up from beside the hip. Everything else is a plain cascade.","goodFor":"A blind catch behind the back, timed by feel instead of sight.","alignmentCues":["Throw high enough to clear your head, just behind the left shoulder.","Get the catching hand behind the hip early, palm turned up."],"commonMistakes":["Turning the head to look for the ball.","Throwing too low so the ball clips the head or shoulder."]},"knee-bounce-cascade":{"name":"Knee Bounce","description":"Every sixth throw, the right hand drops its ball onto the right knee as the knee comes up. The ball bounces off the top of the thigh, up and across to the left hand, and the foot goes back down for the next catch.","goodFor":"Balancing on one leg while the knee joins the pattern on the beat.","alignmentCues":["Lift the knee to meet the ball, thigh level.","Drop the ball, do not throw it down."],"commonMistakes":["Kicking at the ball so it flies forward.","Leaning down to the knee instead of lifting it."]},"head-bounce-cascade":{"name":"Head Bounce","description":"Every sixth throw goes up over your head. Tip your head back so the ball lands on your forehead, then nod it down and forward into the left hand. The other throws stay a plain cascade underneath.","goodFor":"Tracking a ball straight above you while the hands keep the cascade going.","alignmentCues":["Tip the head back early and keep your eyes on the ball.","Bend the knees a little to soften the bounce."],"commonMistakes":["Heading the ball instead of letting it land.","Losing the cascade while looking up."]},"crossed-arm-cascade":{"name":"Crossed-Arm Cascade","description":"Cross the forearms with the right hand on the left side and keep them crossed. Juggle a cascade from that position. The throws feel mirrored even though the pattern looks normal.","goodFor":"Breaking the habit of where each hand lives.","alignmentCues":["Keep the cross at the wrists, not the elbows.","Throws peak at eye height as usual."],"commonMistakes":["Uncrossing between throws.","Hands colliding as they swap sides."]},"burkes-barrage":{"name":"Burke's Barrage","description":"Built on 423. The ball thrown as a 4 is clawed and carried across, the 2 is a short lift in the same hand, and the 3 is chopped down into the pattern. The arms weave over each other in a busy flourish.","goodFor":"Combining carries and claws over a siteswap you already know.","alignmentCues":["Learn the 423 timing first, then add the carry.","The 2 barely leaves the hand."],"commonMistakes":["Throwing the 2 so high it breaks the rhythm.","Forgetting the chop on the 3."]},"rubensteins-revenge":{"name":"Rubenstein's Revenge","description":"A tangle of carries over 52233. A high throw buys time while the hands claw, chop and cross through each other, then the pattern unwinds back into a cascade. Learn it slowly, one hand at a time.","goodFor":"A showpiece that trains carries, claws and crossing arms together.","alignmentCues":["The 5 is the only high throw.","Learn the hand path with the high ball left out."],"commonMistakes":["Panicking during the carries and throwing early.","The high throw drifting forward."]},"siteswap-42":{"name":"Two-Ball 42","description":"Two balls: each hand throws one high ball to itself and holds the other for a beat. The high balls rise in columns on each side while the hands take turns. A quiet way to learn self-throws.","goodFor":"Self-throws at four height, the building block of two in one hand.","alignmentCues":["Throws stay on their own side.","Hold the 2 still in the palm."],"commonMistakes":["Throws drifting across the middle.","Throwing the held ball by mistake."]},"snake":{"name":"Snake","description":"Three balls thrown as tall crossing fives with an empty beat after each. The balls trail one after another along the same high arc, like a snake sliding over your head.","goodFor":"Consistent high throws without the pressure of a full five-ball rhythm.","alignmentCues":["All fives the same height.","Use the empty beat to reset the hand."],"commonMistakes":["Fives drifting forward.","Throwing on the empty beat out of habit."]},"grace":{"name":"Grace","description":"A gentle multiplex: one hand throws two balls at once, a normal crossing throw and a tiny pass straight to the other hand. Then a held beat and back to the cascade.","goodFor":"A soft introduction to throwing two balls from one hand.","alignmentCues":["Release both balls together.","The small one barely rises."],"commonMistakes":["Releasing the two balls at different times.","Throwing the small ball too high."]},"orinoco-flow":{"name":"Orinoco Flow","description":"Two rounds of 42 with a cascade throw stitched on the end, so the self-throws switch sides each time around. It ripples between columns and cascade.","goodFor":"Smooth switching between self-throws and crossing throws.","alignmentCues":["Fours straight up beside you.","The 3 is a normal cascade throw."],"commonMistakes":["Fours leaning inwards.","Losing count of the five-throw cycle."]},"relfs-rhythm":{"name":"Relf's Rhythm","description":"A self-throw and a hold, then three cascade throws. Because the cycle is odd, the self-throw lands on the other hand each time round.","goodFor":"Inserting a trick into a running cascade on either side.","alignmentCues":["Cascade first, then drop in the 42.","Keep the four on its own side."],"commonMistakes":["Only ever doing it on the strong hand.","The cascade speeding up afterwards."]},"frostbite":{"name":"Frostbite","description":"Two quick fours, a fast pass across, then two cascade throws. The pass sneaks underneath while the fours hang overhead.","goodFor":"Mixing fast passes with tall throws in one cycle.","alignmentCues":["The 1 is a flick straight across.","Fours stay vertical."],"commonMistakes":["Lobbing the 1 instead of passing it.","Forgetting the second four."]},"siteswap-52512":{"name":"52512","description":"Two high fives split by a held beat, then a five, a quick pass and a hold. The pattern mixes high crossing throws with short low ones.","goodFor":"Precise high-low control at three balls.","alignmentCues":["Fives all reach the same height.","Twos stay in the hand."],"commonMistakes":["Throwing the 2s.","Uneven fives."]},"high-low-shower":{"name":"High-Low Shower","description":"A shower with a twist: one ball goes very high while the others zip across low and fast underneath. The rhythm sounds like a gallop.","goodFor":"Big height contrast and quick hands in a three-ball pattern.","alignmentCues":["Seven goes high and straight.","Ones are flat passes."],"commonMistakes":["Sevens drifting forward.","Ones arcing too high."]},"siteswap-612":{"name":"612","description":"A tall self-throw, a quick pass and a hold. The six goes up beside you on the same side, while the other two balls swap across underneath.","goodFor":"High self-throws mixed with fast low passes.","alignmentCues":["The six stays on its side.","Pass the 1 flat and fast."],"commonMistakes":["Six crossing over.","Holding too long on the 2."]},"three-in-one":{"name":"Three in One Hand","description":"Three balls juggled with only the right hand in high columns or a small fountain. Each throw is tall so there is time to catch and throw again.","goodFor":"One-hand control and height consistency.","alignmentCues":["Throws peak well above the head.","Keep the hand moving in a small circle."],"commonMistakes":["Throws drifting outward.","Throws too low to keep three going."]},"columns":{"name":"Columns","description":"Three balls rising in vertical columns. Both hands throw their outside balls together, then the right throws the middle ball by itself. Up, up, up, like pistons.","goodFor":"First simultaneous throws and a base for many sync tricks.","alignmentCues":["Outside columns go up together.","Middle column straight up from the centre."],"commonMistakes":["Columns tilting so balls collide.","Uneven timing on the pair."]},"infinity":{"name":"Infinity","description":"A column pattern where the single throw goes across instead of straight up, so the middle ball swaps sides each time. The balls trace a figure of eight.","goodFor":"Switching a sync pattern between sides.","alignmentCues":["Pair straight up, single across.","Sides alternate every cycle."],"commonMistakes":["Single throw going straight up out of habit.","Pair drifting."]},"rainbow-cross":{"name":"Rainbow Cross","description":"Two balls cross over each other in a pair, then one goes straight up the middle. The crossing arcs make a rainbow above your head.","goodFor":"Crossing sync throws without collisions.","alignmentCues":["One crossing throw slightly in front of the other.","Middle throw goes straight up."],"commonMistakes":["The crossing balls hitting each other.","Middle throw leaning."]},"crossunder":{"name":"Crossunder","description":"Every throw crosses: a crossing pair, then a single crossing throw that switches sides each cycle. The balls loop over and under each other.","goodFor":"All-crossing sync control.","alignmentCues":["Keep crossing throws in slightly different planes.","Even height throughout."],"commonMistakes":["Clashes in the middle.","Single throw too short."]},"yo-yo":{"name":"Yo-Yo","description":"One hand throws columns while the other hand holds a ball and moves up and down beneath one of them, as if the two balls are joined by a string.","goodFor":"An illusion that teaches a moving held ball against a column.","alignmentCues":["Held ball shadows the column ball.","Columns stay vertical."],"commonMistakes":["The held ball lagging behind.","Columns drifting apart."]},"box":{"name":"Box","description":"The balls trace a square. One hand throws a ball straight up while the other passes a ball across, then the roles swap. Tall sides, flat top and bottom.","goodFor":"A classic sync pattern that trains horizontal passes.","alignmentCues":["Passes go straight across at hand height.","Verticals rise straight up."],"commonMistakes":["Passes arcing too high.","Columns leaning in."]},"broken-box":{"name":"Broken Box","description":"A box that switches sides every throw: the vertical throw and the cross pass alternate hands, so the square keeps folding over itself.","goodFor":"Fast sync role-switching.","alignmentCues":["Alternate the vertical every beat.","Pass flat and quick."],"commonMistakes":["Repeating the vertical on the same side.","Rushing the pass."]},"als-slide":{"name":"Al's Slide","description":"A crossing high throw paired with a flat pass, then a hold and another crossing high throw. The balls slide across the top and bottom in a smooth rolling shape.","goodFor":"Sync crossing throws mixed with passes and holds.","alignmentCues":["Crossing fours peak together.","Hold the 2 still."],"commonMistakes":["Throwing the held ball.","Clashing in the middle."]},"factory":{"name":"Factory","description":"One hand works like a conveyor belt, carrying balls across at waist level, while the other hand throws columns. Balls loop round in a machine-like cycle.","goodFor":"Carry-and-throw coordination in a sync rhythm.","alignmentCues":["The carrying hand moves in a wide loop.","Verticals stay tall."],"commonMistakes":["Carry hand dropping balls into the column.","Columns leaning."]},"broken-shower":{"name":"Broken Shower","description":"A synchronous shower: the right hand throws high across while the left passes low across at the same time. The balls circle in a tight loop.","goodFor":"A sync version of the shower loop.","alignmentCues":["Both hands release together.","High arc for the right, flat pass for the left."],"commonMistakes":["Releasing one after the other.","Pass arcing up into the high ball."]},"crossed-arm-shower":{"name":"Crossed-Arm Shower","description":"The shower juggled with the forearms crossed. The high throws come from the left side of your body and the quick passes go back underneath.","goodFor":"Shower control in an unfamiliar arm position.","alignmentCues":["Stay crossed throughout.","Pass close to the body."],"commonMistakes":["Uncrossing to make catches.","Passes too high."]},"siteswap-534":{"name":"534","description":"A four-ball pattern mixing a crossing five, a cascade three and a self four. It feels like a four-ball 423 and connects neatly to the fountain.","goodFor":"The most popular four-ball trick, and a way into higher siteswaps.","alignmentCues":["Five highest, three lowest.","Four stays on its side."],"commonMistakes":["Flattening the heights.","Rushing the three."]},"siteswap-552":{"name":"552","description":"Two crossing fives and a hold. Four balls are juggled in a five-ball rhythm with one beat to breathe.","goodFor":"Five-height throws with time to recover.","alignmentCues":["Both fives identical.","Hold the 2 still."],"commonMistakes":["Throwing the hold.","Fives drifting forward."]},"siteswap-5551":{"name":"5551","description":"Three fives in a row and a quick pass. A good stepping stone towards a five-ball cascade.","goodFor":"Practising runs of fives with four balls.","alignmentCues":["Fives all the same height.","Flat fast pass for the 1."],"commonMistakes":["Fives creeping lower.","Lobbing the 1."]},"siteswap-55550":{"name":"55550","description":"Four fives and an empty hand. A five-ball cascade with one ball missing, which makes it a great five-ball rehearsal.","goodFor":"The last step before five-ball cascade.","alignmentCues":["Use the gap to settle.","Fives consistent."],"commonMistakes":["Throwing into the gap.","Fives drifting."]},"siteswap-633":{"name":"633","description":"A tall self-throw then two cascade throws. The six hangs above while the cascade runs underneath.","goodFor":"High self-throws woven into a four-ball rhythm.","alignmentCues":["The six stays above its own hand.","Threes stay low."],"commonMistakes":["Six drifting across.","Threes too high."]},"siteswap-53":{"name":"53","description":"One hand throws high crossing fives while the other throws low cascade threes. A half-and-half shower of four balls.","goodFor":"Height control between the two hands.","alignmentCues":["Right hand high, left hand low.","Even rhythm."],"commonMistakes":["Heights converging.","Rushing the threes."]},"wimpy":{"name":"Wimpy Pattern","description":"Four balls with every pair crossing at the same time. Arcs swap sides each beat in a wide criss-cross.","goodFor":"Crossing sync at four balls.","alignmentCues":["One hand throws a touch in front.","Release together."],"commonMistakes":["Clashing in the middle.","Staggering the release."]},"four-ball-shower":{"name":"Four-Ball Shower","description":"Four balls in a circle: very high throws from one hand and flat passes from the other.","goodFor":"High throw consistency at four balls.","alignmentCues":["Sevens straight and high.","Passes quick and flat."],"commonMistakes":["Sevens drifting forward.","Passes rising."]},"tsunami":{"name":"Tsunami","description":"A high seven, a hold, a self four, a pass and a tall self six. Waves of height crash through the pattern.","goodFor":"Advanced mixed-height four-ball control.","alignmentCues":["Learn the throws slowly in order.","Seven and six both go high."],"commonMistakes":["Heights inconsistent.","Losing the count."]},"siteswap-645":{"name":"645","description":"The five-ball version of 534: a tall self six, a self four and a crossing five.","goodFor":"A first trick out of the five-ball cascade.","alignmentCues":["Six highest.","Four stays on its side."],"commonMistakes":["Flattening heights.","Drifting."]},"siteswap-744":{"name":"744","description":"A very high crossing seven followed by two self fours.","goodFor":"High-throw insertion in five balls.","alignmentCues":["Seven straight and tall.","Fours vertical."],"commonMistakes":["Seven drifting.","Fours crossing."]},"five-ball-shower":{"name":"Five-Ball Shower","description":"Five balls in a loop: towering nines from one hand and flat passes back underneath.","goodFor":"Height and accuracy at the top of the scale.","alignmentCues":["Nines straight and consistent.","Passes flat."],"commonMistakes":["Nines wandering.","Passes rising."]},"five-ball-half-shower":{"name":"Five-Ball Half Shower","description":"Synchronous crossing throws, one hand higher than the other, with five balls.","goodFor":"Sync crossing control at five balls.","alignmentCues":["Right higher, left lower.","Release together."],"commonMistakes":["Heights converging.","Clashes."]},"martins-one-count":{"name":"Martin's Pattern","description":"A multiplex: a high six and a held ball released together, then a hold and a crossing five.","goodFor":"Multiplex timing at five balls.","alignmentCues":["The multiplex releases cleanly.","Five crosses."],"commonMistakes":["Splitting the multiplex.","Six drifting."]},"six-ball-fountain":{"name":"Six-Ball Fountain","description":"Three balls in each hand, juggled in tall fountains side by side.","goodFor":"The six-ball numbers milestone.","alignmentCues":["Each hand runs its own fountain.","Throws high and consistent."],"commonMistakes":["Fountains drifting together.","Throws too low."]},"club-swing":{"name":"Single Club Spin","description":"Hold one club by the handle, knob tucked into the heel of your hand. Swing it up from the waist so it turns once in the air and arrives handle first in the other hand. Toss it back the same way.","goodFor":"Learning the single spin that every club pattern is made from.","alignmentCues":["Lift from the elbow, let the wrist roll the club over.","Catch the handle at waist height."],"commonMistakes":["Flicking the wrist so the club over-spins.","Throwing forward so the handle lands far away."]},"club-exchange":{"name":"Two-Club Exchange","description":"A club in each hand. Throw a single spin from the right; as it peaks, throw the left club underneath it. Catch both by the handles and pause, then lead with the other hand.","goodFor":"Timing two spinning clubs without collisions.","alignmentCues":["Second club goes on the peak of the first.","Throw the second club inside the first."],"commonMistakes":["Clubs clattering together in the middle.","Uneven spin between hands."]},"club-cascade":{"name":"Three-Club Cascade","description":"The cascade with clubs, each turning one spin. Throws come from the inside of the body and travel across, with the club handles kept pointing at you.","goodFor":"The foundation pattern for all club juggling.","alignmentCues":["Throw from the elbow, keep wrists soft.","Clubs stay parallel to your chest."],"commonMistakes":["Clubs tilting so they rotate sideways.","Spinning too fast and catching the body."]},"club-doubles":{"name":"Club Doubles","description":"A three-club cascade where every club turns twice in the air. The throws are taller and slower, and the clubs blur in big circles.","goodFor":"Spin control and the height needed for four clubs.","alignmentCues":["Lift more from the arm, not the wrist.","Keep the double spin smooth and even."],"commonMistakes":["Snapping the wrist and over-spinning.","Throwing doubles too low."]},"club-flats":{"name":"Club Flats","description":"A cascade where the clubs do not spin at all. Each club floats across handle down, pushed up by a straight wrist, and is caught upright.","goodFor":"Wrist control, and an easy contrast with spinning throws.","alignmentCues":["Lock the wrist and push from the elbow.","The club stays upright the whole way."],"commonMistakes":["Accidental half spins.","Throwing too high so the club wobbles."]},"club-under-leg":{"name":"Club Under the Leg","description":"A club cascade with every sixth throw passed under the right leg. Lift the knee, swing the club under the thigh and let it spin up into the pattern.","goodFor":"The first body throw with clubs.","alignmentCues":["Knee up early.","A little extra height on the leg throw."],"commonMistakes":["Hitting the leg with the club.","Bending over instead of lifting the knee."]},"club-behind-back":{"name":"Club Behind the Back","description":"A club cascade where every sixth throw is swung behind the waist and sent over the opposite shoulder into the pattern.","goodFor":"Blind club throws behind the body.","alignmentCues":["Swing the arm behind early.","Aim over the far shoulder."],"commonMistakes":["Club landing too far in front.","Twisting the torso."]},"club-four-fountain":{"name":"Four-Club Fountain","description":"Two clubs in each hand, each hand throwing doubles in its own fountain. The clubs never cross the middle.","goodFor":"The four-club milestone.","alignmentCues":["Doubles on their own side.","Hands alternate evenly."],"commonMistakes":["Clubs drifting into the centre.","Spinning unevenly between hands."]},"ring-cascade":{"name":"Three-Ring Cascade","description":"The cascade with rings held edge on, like a steering wheel seen from the side. Each ring flies through the pattern without turning, so the edges slice the air cleanly.","goodFor":"A simple way to try rings and feel how they float.","alignmentCues":["Hold the ring edge on to you.","Release with a straight wrist."],"commonMistakes":["Rings wobbling from a cocked wrist.","Throwing them face on so they catch the wind."]},"ring-pancakes":{"name":"Ring Pancakes","description":"A ring cascade where each ring flips flat at the top of its throw and back to edge on for the catch, like a pancake turned in a pan.","goodFor":"Wrist control and a showy ring flourish.","alignmentCues":["A quick wrist turn at release.","Catch the ring edge on again."],"commonMistakes":["Over-flipping.","Throwing low so the ring cannot turn."]},"ring-four-fountain":{"name":"Four-Ring Fountain","description":"Two rings in each hand, juggled in separate fountains, edges cutting straight up and down.","goodFor":"Four objects with a light, floating prop.","alignmentCues":["Rings stay edge on.","Each hand runs its own column."],"commonMistakes":["Rings touching in the middle.","Throws drifting forward."]},"hoop-juggle-single":{"name":"Single Hoop Toss","description":"Hold a hoop by the edge, hanging beside you. Toss it in a soft arc to the other hand so it travels edge on and arrives at the same height it left.","goodFor":"Learning how a full-size hoop flies before adding more.","alignmentCues":["Keep the hoop edge on to your chest.","Toss from the shoulder, not the wrist."],"commonMistakes":["Throwing it face on so it floats away.","Throwing low and grabbing."]},"hoop-juggle-exchange":{"name":"Two-Hoop Exchange","description":"A hoop in each hand. Toss the right hoop; as it peaks, toss the left one underneath. The hoops pass close, one in front of the other.","goodFor":"Two-hoop timing and keeping the hoops from colliding.","alignmentCues":["Second hoop on the peak of the first.","Throw the second slightly in front."],"commonMistakes":["Hoops hitting each other.","Throwing both too fast."]},"hoop-juggle-cascade":{"name":"Three-Hoop Cascade","description":"The cascade with full-size hoops. The hands stay wide, the throws are big and slow, and each hoop turns edge on through the pattern.","goodFor":"The base pattern for hoop juggling.","alignmentCues":["Arms wide, elbows soft.","Every hoop in the same plane."],"commonMistakes":["Hoops drifting forward.","Rushing the throws."]},"hoop-juggle-reverse":{"name":"Reverse Hoop Cascade","description":"Hoops thrown over the top from the outside and caught on the inside, the reverse cascade on a big scale.","goodFor":"Outside throws with hoops.","alignmentCues":["Throw from the outside, over the top.","Catch near the middle."],"commonMistakes":["Hoops landing too wide.","Uneven arcs."]},"hoop-juggle-shower":{"name":"Hoop Shower","description":"Three hoops in a circle: tall throws from one hand and quick handoffs back underneath.","goodFor":"Height and pass control with hoops.","alignmentCues":["High throws straight up and across.","Pass close to the body."],"commonMistakes":["High throws drifting.","Passes rising."]},"hoop-juggle-two-in-one":{"name":"Two Hoops in One Hand","description":"Two hoops juggled by the right hand alone, rising in columns beside you.","goodFor":"One-hand hoop control.","alignmentCues":["Columns stay vertical.","Throw high to buy time."],"commonMistakes":["Hoops drifting outward.","Too low."]},"hoop-juggle-423":{"name":"Hoop 423","description":"The 423 siteswap with three hoops: a self four, a held two and a crossing three.","goodFor":"Siteswap variety with hoops.","alignmentCues":["Four stays on its own side.","Hold the 2."],"commonMistakes":["Throwing the 2.","Four drifting across."]},"hoop-juggle-441":{"name":"Hoop 441","description":"Two self fours and a fast handoff with hoops. The handoff slips beneath the high pair.","goodFor":"Fast handoffs between tall hoop throws.","alignmentCues":["Fours vertical.","Handoff flat."],"commonMistakes":["Handoff lobbed.","Fours drifting."]},"hoop-juggle-four":{"name":"Four-Hoop Fountain","description":"Two hoops in each hand, juggled in side-by-side fountains.","goodFor":"The four-hoop milestone.","alignmentCues":["Each side separate.","Even rhythm."],"commonMistakes":["Hoops drifting together.","Throws too low."]},"hoop-juggle-under-leg":{"name":"Hoop Under the Leg","description":"A hoop cascade with every sixth throw passed under the raised right leg.","goodFor":"Body throws with a large prop.","alignmentCues":["Lift the knee high.","Throw a little higher."],"commonMistakes":["Hoop catching the foot.","Leaning forward."]},"hoop-juggle-back-throw":{"name":"Hoop Back Throw","description":"A hoop cascade where every sixth throw goes behind the back and over the far shoulder.","goodFor":"Blind throws with hoops.","alignmentCues":["Swing behind early.","Over the far shoulder."],"commonMistakes":["Hoop landing in front.","Twisting."]},"hoop-juggle-body-hoop":{"name":"Juggling While Waist Hooping","description":"Keep one hoop turning on the waist while juggling three more in a cascade. The hips keep their own rhythm under the arms.","goodFor":"Splitting attention between body hooping and juggling.","alignmentCues":["Hips drive the body hoop, arms stay independent.","Keep the juggling plane in front of the body hoop."],"commonMistakes":["Body hoop slowing while you focus on the juggling.","Arms dropping into the body hoop."]},"pass-one-ball":{"name":"One-Ball Pass","description":"Stand facing your partner about two and a half metres apart. Throw one ball from your right hand in a gentle arc to their left hand. They hand it across to their right and throw it back to your left, and you hand it across to your right again.","goodFor":"Learning the height and distance of a pass before any juggling.","alignmentCues":["Throw straight across, not crossing over.","The peak is just above head height, halfway between you.","Look at your partner, not the ball in your hand."],"commonMistakes":["Throwing at the partner’s face instead of up in an arc.","Aiming at their right hand, so the pass crosses."]},"pass-hand-across":{"name":"Two-Ball Passing","description":"Two balls each. Both of you pass from the right on the same beat. Each left hand catches the incoming pass and hands it straight across to the right, ready for the next pass. Nothing is thrown to yourself, so it is all about timing the passes together.","goodFor":"Passing on a shared beat before adding the cascade.","alignmentCues":["Pass together: right hands on the count.","Catch with the left, hand across low and quick."],"commonMistakes":["One of you passing early so the passes cross in the air at different times.","Throwing the hand-across instead of handing it."]},"pass-six-count":{"name":"Six-Count","description":"Both of you juggle a three-ball cascade and pass every sixth throw, always from the right hand to your partner’s left. Between passes you have five self throws to settle the pattern.","goodFor":"The first full passing pattern: plenty of time between passes.","alignmentCues":["Count out loud: pass, two, three, four, five, six.","Keep your selfs the same height as the pass.","Look at your partner, not your own hands."],"commonMistakes":["Losing the count and passing on the wrong beat.","Passing short so your partner has to lunge."]},"pass-four-count":{"name":"Four-Count","description":"Pass every fourth throw, every other right-hand throw. Pass, self, self, self, then pass again. This is the standard club passing warm-up and the base for most variations.","goodFor":"The everyday passing pattern; most tricks start from here.","alignmentCues":["Right hands pass together.","Three selfs, then the pass comes round again."],"commonMistakes":["Collapsing the selfs to make time for the pass.","Turning the shoulders to throw instead of using the forearm."]},"pass-three-count":{"name":"Three-Count","description":"Pass every third throw, so the passes alternate hands: right, then left, then right. Each left-hand pass goes straight across to your partner’s right hand.","goodFor":"Passing from both hands and catching passes in both.","alignmentCues":["Left-hand passes go straight across, like the right.","Keep the pass height the same from both hands."],"commonMistakes":["A weak left-hand pass that drops short.","Crossing the left pass over to their left hand."]},"pass-two-count":{"name":"Two-Count","description":"Every right-hand throw is a pass and every left-hand throw is a self. Pass, self, pass, self. Twice as many passes as a four-count with the same footwork.","goodFor":"Fast, even passing rhythm; the gateway to seven-object patterns.","alignmentCues":["Right hand passes, left hand selfs.","Keep the left self inside, under the incoming pass."],"commonMistakes":["Letting the selfs get lower and lower.","Catching passes too close to the body."]},"pass-left-two-count":{"name":"Left-Handed Two-Count","description":"The two-count mirrored: every left-hand throw is a pass, straight across to your partner’s right hand, and the right hand throws selfs.","goodFor":"Evening out your weaker passing hand.","alignmentCues":["Left passes straight across, not crossing.","Same height and push as your right-hand passes."],"commonMistakes":["Passing short from the weak hand.","Switching back to right-hand passes by habit."]},"pass-ultimates":{"name":"Ultimates","description":"Every throw is a pass. Right hands pass straight across to left hands and left hands pass straight across to right hands; nobody throws a self. The balls make a constant stream between you.","goodFor":"Passing accuracy and rhythm under pressure.","alignmentCues":["Every throw goes across: right, left, right, left.","Catch and pass in one flowing scoop."],"commonMistakes":["Holding a ball and breaking the stream.","Passes getting flatter as the tempo rises."]},"club-pass-four-count":{"name":"Club Four-Count","description":"The four-count with clubs. Each pass is a single spin thrown from the right hand to your partner’s left, arriving handle first. Three single selfs between passes.","goodFor":"The standard start to every club passing session.","alignmentCues":["Pass from beside the right hip with a straight-ahead swing.","A single spin: the handle should land in your partner’s hand."],"commonMistakes":["Over-spinning so the pass arrives knob first.","Passing across the body to your partner’s right."]},"club-pass-two-count":{"name":"Club Two-Count","description":"Every right-hand throw is a single pass and every left-hand throw is a single self. The core rhythm of club passing.","goodFor":"Steady club passing rhythm.","alignmentCues":["Pass, self, pass, self, on even beats.","Keep the left self tight and inside."],"commonMistakes":["Dropping the spin on the left self.","Passes wandering left and right."]},"club-pass-three-count":{"name":"Club Three-Count","description":"Club passes every third throw, so they alternate hands. Left-hand passes go straight across to your partner’s right.","goodFor":"Club passes from the weak hand.","alignmentCues":["Same swing from both hands.","Right then left then right: count it out."],"commonMistakes":["Left-hand passes with too little spin.","Turning the body for the left pass."]},"club-pass-doubles":{"name":"Club Four-Count with Doubles","description":"A four-count where every pass is a double spin, thrown higher so it lands one beat later. To make room, the left hand holds its club for a beat after the pass instead of throwing.","goodFor":"The double pass, the first step to seven-club passing.","alignmentCues":["A double pass is higher and slower: two full turns.","Hold the left club through the pass, then carry on."],"commonMistakes":["Throwing the double as fast as a single, so it over-rotates.","Throwing the left club instead of holding."]},"club-pass-ultimates":{"name":"Club Ultimates","description":"Every throw is a single club pass, alternating right and left. Six clubs stream between you with no selfs.","goodFor":"Club passing accuracy at full rate.","alignmentCues":["Catch and pass in one swing.","Straight passes: right to left, left to right."],"commonMistakes":["Passes drifting into the middle and colliding.","Holding a club and breaking the stream."]},"club-pass-seven-doubles":{"name":"Seven-Club Crossing Doubles","description":"Seven clubs between you. Your right hand passes a crossing double to your partner’s right hand on every other throw, and their left hand answers one throw later with a crossing double to your left. Singles fill the gaps.","goodFor":"A first seven-club pattern, built on doubles.","alignmentCues":["Your doubles cross to the partner’s right hand.","Catch their double in your left, just after your own pass."],"commonMistakes":["Passing straight instead of crossing.","Doubles too low to finish two turns."]},"staff-wheel-spin":{"name":"Two-Hand Wheel Spin","description":"Hold the staff in the middle with both hands, palms down, at chest height. Turn it at your side like a wheel by passing the rotation between the hands, keeping it beside your body.","goodFor":"The first staff spin; builds grip and wrist rotation.","alignmentCues":["The staff stays parallel to your body, never tilting.","Soft grip: let it roll through the fingers."],"props":["staff"],"commonMistakes":["Squeezing so the spin stalls.","Tilting the plane forward."]},"staff-front-spin":{"name":"Front Windmill","description":"Spin the staff in front of you like a propeller, in the wall plane, passing it smoothly from hand to hand around its centre.","goodFor":"Adds the wall plane and hand-over-hand passing.","props":["staff"]},"staff-figure-8":{"name":"Figure-8 Weave","description":"Spin the staff in the wheel plane on your right side, then cross it over to your left side and spin there, tracing a figure-8 in front of you.","goodFor":"Links both sides of the body; the backbone of staff flow.","alignmentCues":["Switch sides as the tips pass the floor.","Rotate the torso a little with each side."],"props":["staff"]},"staff-pass-through":{"name":"Pass-Through","description":"Spin in the wall plane but let go each half turn: one hand releases the staff and the other catches it at the centre, so the staff passes between your hands.","goodFor":"Teaches release and catch timing.","props":["staff"]},"staff-one-hand-spin":{"name":"One-Hand Spin","description":"Spin the staff in front of you with one hand, rolling it over the back of the hand and through the fingers. Practise both hands.","goodFor":"Finger and wrist strength; frees the other hand for tricks.","props":["staff"]},"staff-helicopter":{"name":"Overhead Helicopter","description":"Lift the staff overhead and spin it flat in the floor plane with one hand, like helicopter blades.","goodFor":"Introduces the floor plane.","props":["staff"]},"staff-butterfly":{"name":"Butterfly","description":"Spin in front of you, then fold the staff behind your shoulder and back out, alternating front and back on each side like wings.","goodFor":"Shoulder mobility and a flowing front-to-back transition.","props":["staff"]},"staff-behind-back-pass":{"name":"Behind-the-Back Pass","description":"Pass the spinning staff from one hand to the other behind your back at the bottom of the spin, then bring it around to the front.","goodFor":"Body wraps and showpiece passes.","props":["staff"]},"staff-isolation":{"name":"Staff Isolation","description":"Hold the staff near one end and circle your hand around the centre of the staff, so the centre appears to stay fixed in the air while the staff turns around it.","goodFor":"Illusion work and precise hand paths.","props":["staff"]},"staff-antispin-flower":{"name":"Four-Petal Antispin","description":"Circle your hand one way while the staff spins the other way three times as fast, so the staff draws a four-petal flower.","goodFor":"The signature VTG flower; deep timing control.","props":["staff"]},"staff-neck-roll":{"name":"Neck Roll","description":"Release the staff onto the back of your shoulders and let it roll across the neck to the other hand. Start slowly with a padded staff.","goodFor":"Contact staff: the staff moves on the body without hands.","avoidIf":["Neck pain."],"props":["staff"]},"staff-reverse-wheel":{"name":"Reverse Wheel Spin","description":"The wheel spin turned the other way: the front end of the staff rises and travels back over the top. Both hands stay on the middle and roll it through, exactly as in the forward spin.","goodFor":"Balancing both spin directions so every later move works either way.","alignmentCues":["Same flat wheel beside you, only the direction changes.","Lead with the knuckles rolling back."],"props":["staff"],"commonMistakes":["The plane drifting across your body.","Switching back to forward without noticing."]},"staff-reverse-front-spin":{"name":"Reverse Front Spin","description":"A two-handed front spin going the opposite way round. The top end falls towards your right instead of your left.","goodFor":"Both directions of the front spin before passing or weaving.","alignmentCues":["Keep the staff square in front of the chest.","Hands swap over the same way, just reversed."],"props":["staff"],"commonMistakes":["Ends tipping towards you.","Losing the rhythm at the hand swap."]},"staff-one-hand-wheel":{"name":"One-Hand Wheel Spin","description":"Spin the staff beside you in the wheel plane with only one hand, rolling it over the back of the hand and through the fingers.","goodFor":"One-hand control beside the body: the basis of wheel isolations and double staff.","alignmentCues":["The staff passes just outside the hip.","Elbow stays close to the ribs."],"props":["staff"],"commonMistakes":["The end clipping the leg.","Wrist locking up."]},"staff-wheel-pass":{"name":"Wheel Pass","description":"A wheel spin that changes hands every half turn. Each hand takes the staff as it lies level, carries it round, and hands it on.","goodFor":"Smooth hand changes beside the body.","alignmentCues":["Catch on the level.","The free hand waits close by."],"props":["staff"],"commonMistakes":["Grabbing before the staff is level.","Plane wandering with each pass."]},"staff-two-hand-helicopter":{"name":"Two-Hand Helicopter","description":"The staff spins flat above your head with both hands on it, passing one hand over the other like a rotor.","goodFor":"A gentle first look at the floor plane.","alignmentCues":["Arms soft, staff just above the head.","Hands swap over in front of the face."],"props":["staff"],"commonMistakes":["Staff tilting forward.","Shoulders hunching."]},"staff-overhead-pass":{"name":"Overhead Pass","description":"The helicopter passed from hand to hand above the head, each hand carrying it half a turn.","goodFor":"Hand changes in the floor plane.","alignmentCues":["Pass when the staff points forward and back.","Keep the elbows soft."],"props":["staff"],"commonMistakes":["Dropping the staff behind the head.","Grabbing early."]},"staff-one-hand-reverse":{"name":"One-Hand Reverse Spin","description":"A one-hand front spin turning the other way, rolling over the thumb side first.","goodFor":"One-hand control in both directions.","alignmentCues":["Same plane, same speed, reversed.","Fingers relax as the staff rolls."],"props":["staff"],"commonMistakes":["Wrist tensing.","Spin slowing on one half."]},"staff-reverse-helicopter":{"name":"Reverse Helicopter","description":"The one-hand helicopter turning the other way above the head.","goodFor":"Both directions overhead.","alignmentCues":["Level blades.","Hand stays above the forehead."],"props":["staff"],"commonMistakes":["Tilting forward.","Arm straightening fully."]},"staff-extension":{"name":"Extension","description":"Hold the staff near one end and let it sweep a big circle around your hand, which barely moves. The far end draws a large ring in front of you.","goodFor":"Big shapes and the wrist rolling needed for isolations.","alignmentCues":["The hand is the hub of the circle.","Roll the wrist, do not swing the arm."],"props":["staff"],"commonMistakes":["Swinging from the shoulder.","The circle flattening into an oval."]},"staff-wheel-extension":{"name":"Wheel Extension","description":"An extension beside the body: the staff sweeps a large wheel around the hand at hip height.","goodFor":"Large wheel-plane circles.","alignmentCues":["Keep the circle outside the leg.","Wrist turns, arm stays quiet."],"props":["staff"],"commonMistakes":["Clipping the foot.","Leaning away from the staff."]},"staff-floor-extension":{"name":"Overhead Extension","description":"A flat extension overhead: the staff sweeps around the raised hand like a long rotor blade.","goodFor":"Overhead reach and a dramatic floor-plane shape.","alignmentCues":["Hand above the head.","Blade stays level."],"props":["staff"],"commonMistakes":["Staff dipping behind.","Arm drifting forward."]},"staff-wheel-isolation":{"name":"Wheel Isolation","description":"The isolation beside the body: the centre of the staff stays fixed while the hand circles around it.","goodFor":"Isolation control in a second plane.","alignmentCues":["Pick a spot beside your hip for the centre.","Hand moves in a small circle."],"props":["staff"],"commonMistakes":["Centre wandering.","Plane tilting."]},"staff-floor-isolation":{"name":"Overhead Isolation","description":"An isolation flat above the head, the staff pivoting on a fixed point as the hand circles.","goodFor":"Overhead isolations.","alignmentCues":["Fixed point above you.","Small hand circle."],"props":["staff"],"commonMistakes":["Centre drifting.","Hand circle growing."]},"staff-isolation-pass":{"name":"Isolation Pass","description":"An isolation passed between the hands each half turn, so the fixed point stays still while the hands trade.","goodFor":"Two-handed isolation control.","alignmentCues":["Pass at the bottom of the circle.","Keep the centre fixed through the pass."],"props":["staff"],"commonMistakes":["Centre jumping at the pass.","Hands colliding."]},"staff-antispin-3":{"name":"Three-Petal Antispin","description":"The hand circles one way while the staff spins the other, drawing a flower with three petals.","goodFor":"The first antispin flower.","alignmentCues":["Hand circle slow and round.","Staff spins against it."],"props":["staff"],"commonMistakes":["Petals uneven.","Hand circle collapsing."]},"staff-antispin-5":{"name":"Five-Petal Antispin","description":"A finer antispin flower with five petals, the hand circling more slowly against the spin.","goodFor":"Precise antispin timing.","alignmentCues":["Count the petals.","Hand moves slowly."],"props":["staff"],"commonMistakes":["Petals merging.","Rushing the hand."]},"staff-wheel-antispin":{"name":"Wheel Antispin","description":"An antispin flower drawn beside the body in the wheel plane.","goodFor":"Flowers in a second plane.","alignmentCues":["Upright plane.","Even petals."],"props":["staff"],"commonMistakes":["Plane tilting.","Petals drifting forward."]},"staff-floor-antispin":{"name":"Overhead Antispin","description":"An antispin flower drawn flat above the head.","goodFor":"Overhead flowers.","alignmentCues":["Level plane.","Hand above the head."],"props":["staff"],"commonMistakes":["Tilting.","Petals uneven."]},"staff-inspin-3":{"name":"Three-Petal Inspin","description":"The hand circles the same way as the spin, but slower, and the staff draws three petals pointing inward.","goodFor":"The softest flower to learn.","alignmentCues":["Hand and staff turn the same way.","Hand circle wide and slow."],"props":["staff"],"commonMistakes":["Hand speeding up to match the staff.","Petals lopsided."]},"staff-inspin-4":{"name":"Four-Petal Inspin","description":"An inspin flower with four inward petals.","goodFor":"More inspin control.","alignmentCues":["Count four petals.","Steady hand."],"props":["staff"],"commonMistakes":["Petals merging.","Hand drifting."]},"staff-wheel-inspin":{"name":"Wheel Inspin","description":"A three-petal inspin drawn beside the body.","goodFor":"Inspins in the wheel plane.","alignmentCues":["Upright plane.","Slow hand."],"props":["staff"],"commonMistakes":["Tilting.","Clipping the leg."]},"staff-reverse-figure-8":{"name":"Reverse Figure 8","description":"The figure 8 turned the other way: the staff rises at the front and falls behind on each side.","goodFor":"Both directions of the weave.","alignmentCues":["Cross in front of the body.","Each side vertical."],"props":["staff"],"commonMistakes":["Plane collapsing at the cross.","Torso stiff."]},"staff-front-weave":{"name":"Front Weave","description":"A front spin that drifts from one side of the body to the other each turn, the chest turning with it.","goodFor":"Moving the spin across the body.","alignmentCues":["Chest follows the staff.","Spin stays square to you."],"props":["staff"],"commonMistakes":["Feet turning too.","Plane tilting at the cross."]},"staff-overhead-weave":{"name":"Overhead Weave","description":"A two-handed helicopter that swings from one side of the head to the other each turn.","goodFor":"Weaving in the floor plane.","alignmentCues":["Level blades throughout.","Torso turns with the staff."],"props":["staff"],"commonMistakes":["Dipping on one side.","Head in the way."]},"staff-fountain":{"name":"Fountain","description":"A split-time weave in the wheel plane: the ends spray up and over on alternate sides like water from a fountain.","goodFor":"Split timing beside the body.","alignmentCues":["Ends rise on alternate sides.","Keep the cross quick."],"props":["staff"],"commonMistakes":["Collapsing into a plain figure 8.","Plane tilting."]},"staff-reel":{"name":"Reel","description":"A figure 8 that changes hands at every crossing, the staff reeling from one side to the other.","goodFor":"Combining weaves and passes.","alignmentCues":["Pass at the crossing.","Each side upright."],"props":["staff"],"commonMistakes":["Grabbing early.","Torso stiff."]},"staff-wall-wheel-hybrid":{"name":"Wall-Wheel Hybrid","description":"Every turn the spin swaps between the front plane and the wheel plane beside you, switching when the staff is upright.","goodFor":"Changing planes without stopping.","alignmentCues":["Switch when the staff points straight up.","Wrist turns a quarter."],"props":["staff"],"commonMistakes":["Switching on the level.","Losing speed in the switch."]},"staff-floor-wall-hybrid":{"name":"Wall-Floor Hybrid","description":"The spin alternates between in front of you and overhead, switching each time the staff lies level.","goodFor":"Linking front spins and helicopters.","alignmentCues":["Switch on the level.","Lift the arm smoothly."],"props":["staff"],"commonMistakes":["Switching when vertical.","Elbow locking."]},"staff-floor-wheel-hybrid":{"name":"Floor-Wheel Hybrid","description":"A helicopter that drops into a wheel beside you and back up again every turn.","goodFor":"The full set of plane changes.","alignmentCues":["Arm lifts and drops smoothly.","Planes clean."],"props":["staff"],"commonMistakes":["Muddy middle plane.","Speed dropping."]},"staff-under-leg-pass":{"name":"Under-the-Leg Pass","description":"A pass-through that dips under the lifted right leg every other pass.","goodFor":"Adding the legs to passing moves.","alignmentCues":["Lift the knee high to the staff.","Fold at the hips with a long back and sit into the standing knee.","Come back up as the staff clears the leg."],"props":["staff"],"commonMistakes":["Rounding the back to reach down instead of folding at the hips.","Leaving the knee low so the staff has to dive under it.","Rushing the pass under the leg."]},"staff-reverse-behind-back":{"name":"Reverse Behind-the-Back Pass","description":"The behind-the-back pass travelling the other way round the body, the spin running in reverse.","goodFor":"Taking the staff round the body in both directions.","alignmentCues":["The hand behind waits low.","Keep the spin going behind."],"props":["staff"],"commonMistakes":["Losing the plane behind.","Stopping the spin."]},"staff-fishtail":{"name":"Fishtail","description":"The staff rocks back and forth across the open palm like a fish flicking its tail, never quite turning all the way round.","goodFor":"Open-hand control and changing spin direction.","alignmentCues":["Pivot between thumb and fingers.","Small wrist flicks reverse the swing."],"props":["staff"],"commonMistakes":["Gripping too hard.","Swings growing too big."]},"staff-wheel-fishtail":{"name":"Wheel Fishtail","description":"A fishtail beside the body in the wheel plane.","goodFor":"Fishtails in a second plane.","alignmentCues":["Upright plane.","Open hand."],"props":["staff"],"commonMistakes":["Tilting.","Gripping."]},"staff-steering-wheel":{"name":"Steering Wheel","description":"Turn the staff hand over hand with flat open palms, as if turning a big steering wheel in front of you.","goodFor":"Relaxed hands and open-palm contact.","alignmentCues":["Palms flat, fingers soft.","Hand over hand at the top."],"props":["staff"],"commonMistakes":["Grabbing instead of guiding.","Elbows flaring."]},"staff-palm-spin":{"name":"Palm Spin","description":"Balance the middle of the staff on the flat raised palm and let it spin there like a propeller.","goodFor":"Balance and a light touch overhead.","alignmentCues":["Palm flat and level.","Small circles keep it turning."],"props":["staff"],"commonMistakes":["Palm tilting.","Pushing instead of nudging."]},"staff-hand-roll":{"name":"Hand Roll","description":"The staff rolls over the back of the open hand and around the thumb without being gripped.","goodFor":"The first true contact roll.","alignmentCues":["Hand open and soft.","Let the staff do the work."],"props":["staff"],"commonMistakes":["Closing the fingers.","Hand moving too much."]},"staff-forearm-roll":{"name":"Forearm Roll","description":"Release the spin onto the forearm, let the staff turn over it, then pick it back up into the hand spin.","goodFor":"Moving a spin onto the arm and back.","alignmentCues":["Forearm level and still.","Open the hand as it lands."],"props":["staff"],"commonMistakes":["Forearm tilting.","Grabbing too soon."]},"staff-elbow-roll":{"name":"Elbow Roll","description":"The spin moves to the crook of the bent elbow, turns there with the hand lifted, and returns to the hand.","goodFor":"Advanced contact control.","alignmentCues":["Forearm upright.","Elbow still."],"props":["staff"],"commonMistakes":["Elbow dropping.","Staff sliding off."]},"staff-shoulder-roll":{"name":"Shoulder Roll","description":"A wheel spin lifted onto the top of the shoulder, where it turns beside the head before dropping back into the hand.","goodFor":"Contact rolls high on the body.","alignmentCues":["Shoulder lifted slightly.","Head tilts away."],"props":["staff"],"commonMistakes":["Head in the way.","Shoulder dropping."]},"staff-chest-roll":{"name":"Chest Roll","description":"The staff rolls level across the chest from one hand to the other, then back again.","goodFor":"Body contact across the front.","alignmentCues":["Chest lifted.","Staff stays level."],"props":["staff"],"commonMistakes":["Chest collapsing.","Staff tilting."]},"staff-angel-roll":{"name":"Angel Roll","description":"The arms spread wide and the staff rolls across the back of the shoulders and along both arms from one hand to the other.","goodFor":"A showpiece contact roll.","alignmentCues":["Arms level, palms up.","Shoulder blades squeezed."],"props":["staff"],"commonMistakes":["Arms dropping.","Head forward."]},"staff-toss":{"name":"Staff Toss","description":"Release a one-hand spin on the level, let it turn once in the air, and catch it into the same spin.","goodFor":"Releasing and catching a spinning staff.","alignmentCues":["Release when level.","Catch in the middle."],"props":["staff"],"commonMistakes":["Throwing forward.","Catching an end."]},"staff-double-toss":{"name":"Double Toss","description":"A higher toss with two full turns before the catch.","goodFor":"Height and spin control in the air.","alignmentCues":["More lift, same spin.","Eyes on the middle."],"props":["staff"],"commonMistakes":["Over-spinning.","Drifting forward."]},"staff-flat-toss":{"name":"Flat Toss","description":"Toss a helicopter straight up so it turns flat in the air, then catch it overhead.","goodFor":"Tossing in the floor plane.","alignmentCues":["Level release.","Catch above the head."],"props":["staff"],"commonMistakes":["Tilting on release.","Throwing behind."]},"double-staff-same-time":{"name":"Double Staff Same Time","description":"A short staff in each hand, both spinning in front of you in the same direction and in step.","goodFor":"The first double staff pattern.","alignmentCues":["Staffs side by side, one slightly in front.","Both hands the same speed."],"props":["two short staffs"],"commonMistakes":["Staffs clashing.","One hand lagging."]},"double-staff-split-time":{"name":"Double Staff Split Time","description":"Both staffs spin the same way, but one is a quarter turn behind, so one is upright when the other is level.","goodFor":"Independent timing between the hands.","alignmentCues":["One upright, one level.","Steady offset."],"props":["two short staffs"],"commonMistakes":["Falling back into same time.","Clashing."]},"double-staff-wheels":{"name":"Double Staff Wheels","description":"A wheel spin on each side of the body, both turning forward together.","goodFor":"Double staff beside the body.","alignmentCues":["Each wheel outside its hip.","Same speed."],"props":["two short staffs"],"commonMistakes":["Wheels tilting in.","Hands drifting apart."]},"double-staff-split-wheels":{"name":"Double Staff Split Wheels","description":"Wheels on both sides, a quarter turn apart, like walking legs.","goodFor":"Split timing beside the body.","alignmentCues":["One up, one level.","Steady offset."],"props":["two short staffs"],"commonMistakes":["Syncing up.","Tilting."]},"double-staff-windmill":{"name":"Double Staff Windmill","description":"Wheels on both sides turning in opposite directions, like a windmill seen from the side.","goodFor":"Opposite directions in the two hands.","alignmentCues":["One forward, one backward.","Even speed."],"props":["two short staffs"],"commonMistakes":["Both drifting to the same direction.","Uneven speed."]},"double-staff-reverse":{"name":"Double Staff Reverse","description":"Split-time front spins with both staffs running in reverse.","goodFor":"Both directions with two staffs.","alignmentCues":["Hold the offset.","Same plane for both."],"props":["two short staffs"],"commonMistakes":["Clashing.","Losing the offset."]},"double-staff-helicopters":{"name":"Double Staff Helicopters","description":"A helicopter above each shoulder, both turning in step.","goodFor":"Overhead double staff.","alignmentCues":["Level blades.","Arms soft."],"props":["two short staffs"],"commonMistakes":["Blades touching.","Arms tiring and dropping."]},"double-staff-isolations":{"name":"Double Staff Isolations","description":"An isolation in each hand at once, both centres fixed side by side.","goodFor":"Two isolations at once.","alignmentCues":["Two fixed points.","Hands circle together."],"props":["two short staffs"],"commonMistakes":["Centres drifting.","One hand lagging."]},"hoop-waist":{"name":"Waist Hooping","description":"Stand with one foot slightly in front of the other. Hold the hoop against your lower back, throw it around your waist and pulse the belly forward and back (not in circles) every time the hoop passes your front.","goodFor":"The first hoop skill; builds core rhythm.","modifications":["Use a bigger, heavier hoop: it turns more slowly."],"alignmentCues":["Rock front to back, not round in circles.","Push on the hoop as it passes your belly."],"props":["hoop"],"commonMistakes":["Circling the hips like a hula dancer.","A hoop that is too small or light."]},"hoop-hand-spin":{"name":"Hand Spin","description":"Hold the hoop in front of you with the hand inside it, thumb up. Push it into a spin around the web of your hand, keeping the hoop flat in front of you.","goodFor":"Off-body hoop foundation.","props":["hoop"]},"hoop-chest":{"name":"Chest Hooping","description":"Lift your arms overhead and hoop around the chest, rocking the ribcage front to back while keeping the hips quiet.","goodFor":"Isolates the ribcage and builds upper-body control.","props":["hoop"]},"hoop-lasso":{"name":"Lasso","description":"Hold the hoop overhead and circle it flat above your head like a lasso, the hoop spinning around your hand.","goodFor":"Floor-plane control above the head.","props":["hoop"]},"hoop-wedgie":{"name":"Wedgie","description":"Spin the hoop in the wall plane and catch it in the crook between thumb and fingers, letting it roll and rock there before spinning on.","goodFor":"Grip control and a smooth transition hold.","props":["hoop"]},"hoop-knees":{"name":"Knee Hooping","description":"With feet together, keep the hoop turning around your knees by pulsing the knees forward and back.","goodFor":"Lower-body hooping and escalator practice.","props":["hoop"]},"hoop-pass":{"name":"Hand-to-Hand Pass","description":"Spin the hoop in front of you and pass it from one hand to the other each revolution, keeping the plane steady.","goodFor":"Links off-body tricks on both sides.","props":["hoop"]},"hoop-isolation":{"name":"Hoop Isolation","description":"Move your hand around the hoop so its centre stays fixed in the air in front of you while the hoop turns around that point.","goodFor":"The classic hoop illusion.","props":["hoop"]},"hoop-escalator":{"name":"Escalator","description":"Keep the hoop spinning while walking it down from the waist to the knees and back up to the chest, one body zone every bar.","goodFor":"Joins every body-hooping zone into one flow.","props":["hoop"]},"hoop-neck":{"name":"Neck Hooping","description":"Tip the head slightly and let a light hoop spin around the neck, guided by small pulses of the head and shoulders.","goodFor":"A show move that trains small, precise pulses.","avoidIf":["Neck pain."],"props":["hoop"]},"hoop-reverse-waist":{"name":"Reverse Waist Hooping","description":"Waist hooping the other way round. Swap which foot is in front, throw the hoop in the new direction and keep the same front-to-back pulse.","goodFor":"Balancing both directions so every later trick works either way.","alignmentCues":["Swap your front foot.","Same pulse, new direction."],"props":["hoop"],"commonMistakes":["Circling the hips.","Giving up on the weak side too soon."]},"hoop-hips":{"name":"Hip Hooping","description":"Let the hoop sink from the waist to the hip bones and keep it there with a lower, smaller pulse from the pelvis.","goodFor":"Control below the waist and a step towards the knees.","alignmentCues":["Knees soft.","Pulse from the pelvis, not the belly."],"props":["hoop"],"commonMistakes":["Letting it slide on down.","Pulse too big."]},"hoop-thighs":{"name":"Thigh Hooping","description":"With feet close together, keep the hoop turning around the upper thighs using a fast, small knee bounce.","goodFor":"Leg rhythm and the link between hips and knees.","alignmentCues":["Feet together.","Quick small bounces."],"props":["hoop"],"commonMistakes":["Feet apart.","Bouncing too slowly."]},"hoop-reverse-chest":{"name":"Reverse Chest Hooping","description":"Chest hooping in the other direction, arms raised and the ribs driving the hoop.","goodFor":"Both directions high on the body.","alignmentCues":["Arms up and out of the way.","Rib cage rocks front to back."],"props":["hoop"],"commonMistakes":["Arms dropping into the hoop.","Hips doing the work."]},"hoop-shoulder":{"name":"Shoulder Hooping","description":"The hoop turns around the shoulders and upper chest with the arms raised overhead.","goodFor":"Upper body hooping.","alignmentCues":["Arms straight up.","Small shoulder pulses."],"props":["hoop"],"commonMistakes":["Arms bending in.","Hoop slipping to the chest."]},"hoop-arm":{"name":"Arm Hooping","description":"Raise one arm straight up and spin the hoop around the forearm, the hand drawing a small circle to keep it going.","goodFor":"Limb hooping and a raised-arm lasso feel.","alignmentCues":["Arm straight, hand above the head.","Small hand circle."],"props":["hoop"],"commonMistakes":["Circling the whole arm.","Arm drifting forward."]},"hoop-elbow":{"name":"Elbow Hooping","description":"The arm is held out to the side, bent at the elbow, and the hoop turns around the elbow joint.","goodFor":"Limb control away from the body.","alignmentCues":["Upper arm level.","Small elbow circles."],"props":["hoop"],"commonMistakes":["Elbow dropping.","Hoop sliding to the shoulder."]},"hoop-foot":{"name":"Leg Hooping","description":"Lift one leg and spin the hoop around the shin, the foot drawing small circles to keep it turning.","goodFor":"Balance and leg control.","alignmentCues":["Standing leg strong.","Small foot circles."],"props":["hoop"],"commonMistakes":["Losing balance.","Circles too big."]},"hoop-full-escalator":{"name":"Full Escalator","description":"Ride the hoop all the way from the knees to the shoulders and back down without stopping.","goodFor":"The full body range in one continuous move.","alignmentCues":["Speed up the pulse as you climb.","Arms rise as the hoop rises."],"props":["hoop"],"commonMistakes":["Losing it at the waist-chest jump.","Arms in the way."]},"hoop-vortex":{"name":"Vortex","description":"Lasso the hoop overhead, let it drop around the shoulders and chest, and catch it on the waist in one spiralling descent.","goodFor":"Linking off-body and on-body hooping.","alignmentCues":["Keep the lasso speed as you release.","Start pulsing before it lands."],"props":["hoop"],"commonMistakes":["Releasing too slowly.","Hoop tilting on the way down."]},"hoop-duck-out":{"name":"Duck Out","description":"Walk the hoop up from the waist past the chest, grab it overhead into a lasso, then bring it down into a hand spin in front.","goodFor":"Getting off the body cleanly.","alignmentCues":["Lift with the ribs.","Grab overhead on the beat."],"props":["hoop"],"commonMistakes":["Grabbing too early.","Losing speed."]},"hoop-drop-in":{"name":"Drop In","description":"From a lasso overhead, let go and catch the hoop on the chest, then let it drop to the waist.","goodFor":"The simplest way from off-body back to the body.","alignmentCues":["Arms up as it drops.","Catch with a pulse."],"props":["hoop"],"commonMistakes":["Dropping it too fast.","Arms clamping down."]},"hoop-chest-lift":{"name":"Chest Lift","description":"Raise the hoop from the waist to the chest and back with a stronger pulse.","goodFor":"Moving between body zones.","alignmentCues":["Faster pulse to climb.","Arms up early."],"props":["hoop"],"commonMistakes":["Losing it in the change.","Arms dropping."]},"hoop-knee-drop":{"name":"Knee Drop","description":"Let the hoop sink from the waist to the knees, keep it there, then bounce it back up to the waist.","goodFor":"Lower-body transitions.","alignmentCues":["Feet together for the knees.","Bigger bounce to climb."],"props":["hoop"],"commonMistakes":["Feet apart.","Losing it on the climb."]},"hoop-side-spin":{"name":"Side Spin","description":"A hand spin beside the body in the wheel plane, the hoop turning like a wheel next to you.","goodFor":"The wheel plane for hoops.","alignmentCues":["Hoop flat beside you.","Hand at hip height."],"props":["hoop"],"commonMistakes":["Hoop hitting the leg.","Plane tilting."]},"hoop-reverse-hand-spin":{"name":"Reverse Hand Spin","description":"The hand spin turning the other way in front of you.","goodFor":"Both directions off the body.","alignmentCues":["Same plane, other direction.","Thumb stays up."],"props":["hoop"],"commonMistakes":["Wobbling.","Slowing down."]},"hoop-reverse-lasso":{"name":"Reverse Lasso","description":"The overhead lasso turning the other way.","goodFor":"Both lasso directions.","alignmentCues":["Level hoop.","Small hand circle."],"props":["hoop"],"commonMistakes":["Tilting.","Big arm circles."]},"hoop-palm-spin":{"name":"Overhead Palm Spin","description":"A hand spin lifted overhead on the open palm, the hoop turning face-on above you.","goodFor":"Reaching off-body spins up high.","alignmentCues":["Arm long.","Palm open."],"props":["hoop"],"commonMistakes":["Hoop drifting behind.","Arm bending."]},"hoop-coin-flip":{"name":"Coin Flip","description":"Balance the hoop upright on the fingertips and flick it so it spins around its upright middle like a tossed coin.","goodFor":"Fine finger control and a new axis.","alignmentCues":["Hoop upright.","Flick, then let it spin."],"props":["hoop"],"commonMistakes":["Hoop tipping.","Gripping."]},"hoop-cateye":{"name":"Cat Eye","description":"Hold the hoop at the side of the rim and rock it about its upright middle, so from the front it narrows and widens like a cat’s eye.","goodFor":"Rocking moves and a striking illusion.","alignmentCues":["Hand still at the rim.","Rock evenly."],"props":["hoop"],"commonMistakes":["Hand moving.","Uneven swing."]},"hoop-weave":{"name":"Weave","description":"A hand spin that slides from one side of the body to the other, the plane turning with the chest.","goodFor":"Moving the spin across the body.","alignmentCues":["Chest turns with it.","Keep it spinning."],"props":["hoop"],"commonMistakes":["Stopping in the middle.","Tilting."]},"hoop-halo":{"name":"Halo","description":"The hoop orbits flat around the head, the raised hand riding the rim round above you.","goodFor":"Head-level orbits.","alignmentCues":["Hoop level around the head.","Hand close to the head."],"props":["hoop"],"commonMistakes":["Hoop dipping in front.","Ducking."]},"hoop-toss":{"name":"Hoop Toss","description":"Throw a hand spin straight up, still turning, and catch it back into the spin.","goodFor":"Releasing and catching a spinning hoop.","alignmentCues":["Throw straight up.","Catch where you threw."],"props":["hoop"],"commonMistakes":["Throwing forward.","Grabbing the rim late."]},"hoop-boomerang":{"name":"Boomerang","description":"Throw the hoop down and away with backspin so it rolls off along the floor and comes back to you.","goodFor":"Backspin and a fun floor trick.","alignmentCues":["Snap the wrist back.","Throw low and forward."],"props":["hoop"],"commonMistakes":["Not enough backspin.","Throwing too high."]},"hoop-jump-through":{"name":"Jump Through","description":"Hold the hoop in both hands like a skipping rope: swing it over the head and jump through as it passes under your feet.","goodFor":"Rhythm, coordination and a burst of cardio.","alignmentCues":["Small jump, soft knees.","Swing from the wrists."],"props":["hoop"],"commonMistakes":["Jumping too early.","Big arm swings."]},"hoop-behind-back-pass":{"name":"Behind-the-Back Pass","description":"A hand spin passed behind the back from one hand to the other, then back across the front.","goodFor":"Passing all the way round the body.","alignmentCues":["Keep it spinning behind.","The waiting hand reaches back."],"props":["hoop"],"commonMistakes":["Hoop stalling behind.","Hoop hitting the back."]},"hoop-under-leg-pass":{"name":"Under-the-Leg Pass","description":"A hand-to-hand pass that dips under the raised right leg.","goodFor":"Adding the legs to passes.","alignmentCues":["Lift the knee high to the hoop.","Fold at the hips with a long back and sit into the standing knee.","Rise again as the hoop comes out the other side."],"props":["hoop"],"commonMistakes":["Rounding the back to reach down instead of folding at the hips.","Leaving the knee low so the hoop catches the thigh.","Rushing."]},"hoop-corkscrew":{"name":"Corkscrew","description":"A lasso that spirals down to the hips and back up again, the hoop drawing a corkscrew.","goodFor":"Moving a lasso through levels.","alignmentCues":["Bend the knees to go down.","Keep the hoop level."],"props":["hoop"],"commonMistakes":["Hoop tilting low down.","Spin slowing."]},"hoop-barrel-roll":{"name":"Barrel Roll","description":"A hand spin that travels once around the body every four beats, the hoop rolling round you.","goodFor":"Full-circle off-body flow.","alignmentCues":["Turn with the hoop.","Keep spinning throughout."],"props":["hoop"],"commonMistakes":["Hoop catching the body.","Spin stalling behind."]},"hoop-chest-roll":{"name":"Chest Roll","description":"Release a hand spin onto the chest and let it roll across to the other hand.","goodFor":"The first hoop roll.","alignmentCues":["Chest lifted.","Arms open as it rolls."],"props":["hoop"],"commonMistakes":["Chest collapsing.","Grabbing early."]},"hoop-back-roll":{"name":"Back Roll","description":"The hoop rolls across the back of the shoulders from one hand to the other.","goodFor":"Rolls behind the body.","alignmentCues":["Shoulder blades together.","Head forward a touch."],"props":["hoop"],"commonMistakes":["Rounding the back.","Hoop falling."]},"hoop-isopop":{"name":"Iso Pop","description":"An isolation that stalls and pops the hoop out to the side every two beats before carrying on.","goodFor":"Accents and stalls in isolations.","alignmentCues":["Pop on the beat.","Isolation stays clean between pops."],"props":["hoop"],"commonMistakes":["Pops too big.","Centre wandering."]},"hoop-wheel-isolation":{"name":"Side Isolation","description":"An isolation beside the body in the wheel plane.","goodFor":"Isolations in a second plane.","alignmentCues":["Fixed centre beside you.","Hand circles round it."],"props":["hoop"],"commonMistakes":["Centre drifting.","Tilting."]},"hoop-floor-isolation":{"name":"Flat Isolation","description":"An isolation with the hoop lying flat, its centre fixed while the hand circles.","goodFor":"Isolations in the floor plane.","alignmentCues":["Hoop level.","Fixed centre."],"props":["hoop"],"commonMistakes":["Tilting.","Centre drifting."]},"doubles-hand-spins":{"name":"Doubles Hand Spins","description":"A hoop in each hand, both spinning in front of you in mirror image.","goodFor":"The first doubles move.","alignmentCues":["Hoops side by side.","Match the speed."],"props":["two hoops"],"commonMistakes":["Hoops clashing.","One slowing."]},"doubles-offset-spins":{"name":"Doubles Offset Spins","description":"Doubles hand spins turning the same way, half a turn apart.","goodFor":"Independent timing between hands.","alignmentCues":["One up as the other is down.","Same direction."],"props":["two hoops"],"commonMistakes":["Syncing up.","Clashing."]},"doubles-side-spins":{"name":"Doubles Side Spins","description":"A hoop spinning beside each hip in the wheel plane.","goodFor":"Doubles in the wheel plane.","alignmentCues":["Hoops upright.","Clear of the legs."],"props":["two hoops"],"commonMistakes":["Hitting the legs.","Tilting."]},"doubles-floor-spins":{"name":"Doubles Lassos","description":"A lasso overhead in each hand, mirror image.","goodFor":"Overhead doubles.","alignmentCues":["Both level.","Small hand circles."],"props":["two hoops"],"commonMistakes":["Hoops touching.","Arms tiring."]},"doubles-wedgies":{"name":"Doubles Wedgies","description":"A wedgie in each hand, both hoops rocking in the thumb crooks.","goodFor":"Doubles rocking moves.","alignmentCues":["Thumbs out.","Even rocks."],"props":["two hoops"],"commonMistakes":["Hoops clashing.","Uneven timing."]},"doubles-coin-flips":{"name":"Doubles Coin Flips","description":"A coin flip on each hand at once.","goodFor":"Doubles finger control.","alignmentCues":["Both upright.","Flick together."],"props":["two hoops"],"commonMistakes":["Tipping.","Clashing."]},"doubles-isolations":{"name":"Doubles Isolations","description":"An isolation in each hand, both centres fixed side by side.","goodFor":"Two isolations at once.","alignmentCues":["Two still centres.","Hands circle together."],"props":["two hoops"],"commonMistakes":["Centres drifting.","Hoops clashing."]},"doubles-toss":{"name":"Doubles Toss","description":"Toss both spinning hoops up together and catch them back into doubles spins.","goodFor":"Doubles releases.","alignmentCues":["Throw straight up together.","Catch where you threw."],"props":["two hoops"],"commonMistakes":["Uneven throws.","Drifting forward."]},"doubles-waist-and-hand":{"name":"Waist Hoop and Hand Spin","description":"Keep a hoop going on the waist while spinning a second one in the left hand.","goodFor":"Splitting attention between body and hand.","alignmentCues":["Hips keep their pulse.","Hand spin in front of the body hoop."],"props":["two hoops"],"commonMistakes":["Body hoop slowing.","Hand hoop hitting the body hoop."]},"doubles-chest-and-hand":{"name":"Chest Hoop and Hand Spin","description":"Chest hooping with one arm raised while the other hand spins a second hoop.","goodFor":"High body hooping with a hand trick.","alignmentCues":["One arm up.","Ribs drive the body hoop."],"props":["two hoops"],"commonMistakes":["Arm dropping into the chest hoop.","Losing the pulse."]},"doubles-waist-and-lasso":{"name":"Waist Hoop and Lasso","description":"Waist hoop below, lasso overhead: two hoops at two levels at once.","goodFor":"Two levels of hooping together.","alignmentCues":["Hips pulse, hand circles.","Lasso level overhead."],"props":["two hoops"],"commonMistakes":["Body hoop dropping.","Lasso tilting."]},"poi-one-hand-spin":{"name":"One-Poi Forward Spin","description":"One poi circling in front of you like the hand of a clock, the head brushing past your side. The wrist does a small, steady circle and the tether stays tight.","goodFor":"Feeling the tether pull and the rhythm of one turn per beat.","alignmentCues":["Small wrist circles, big poi circles.","Keep the circle flat in front of you, like a window pane."],"props":["one poi"],"commonMistakes":["Swinging from the shoulder.","Letting the circle lean towards you."]},"poi-wall-spin":{"name":"Forward Wall Spin","description":"Both poi turning forward together in front of you, one beside each shoulder, side by side like two wheels on an axle. The first two-poi move.","goodFor":"Two poi in time with each other and the beat.","alignmentCues":["Both heads reach the top together.","Hands about shoulder width apart."],"props":["pair of poi"],"commonMistakes":["One poi lagging behind the other.","Circles drifting into each other."]},"poi-reverse-wall-spin":{"name":"Backward Wall Spin","description":"The wall spin turned the other way round: the heads rise up the outside and fall down the middle.","goodFor":"Both directions before weaves and flowers.","alignmentCues":["Same flat planes, only the direction changes.","Lead the circles with the back of the wrist."],"props":["pair of poi"],"commonMistakes":["Slipping back into forward spin.","Planes leaning forward."]},"poi-split-time":{"name":"Split-Time Wall Spin","description":"Both poi turning the same way, but half a turn apart: when one is at the top the other is at the bottom. The timing every weave is built on.","goodFor":"Independent timing in the two hands.","alignmentCues":["Up, down, up, down: the heads alternate.","Count each poi’s top on the beat and the and."],"props":["pair of poi"],"commonMistakes":["Drifting back into same time.","Hands moving at different speeds."]},"poi-butterfly":{"name":"Butterfly","description":"Hands close together in front, the poi turning in opposite directions so they meet at the top and the bottom like the wings of a butterfly.","goodFor":"Opposite-direction timing and close hands.","alignmentCues":["Heads kiss at the top and at the bottom.","Wrists almost touching."],"props":["pair of poi"],"commonMistakes":["Heads colliding as the planes cross.","Hands drifting apart."]},"poi-reverse-butterfly":{"name":"Reverse Butterfly","description":"The butterfly with both wings turning the other way: the heads rise up the middle together and fall down the outsides.","goodFor":"Balancing the butterfly in both directions.","alignmentCues":["Meet in the middle at the top.","Same close hands as the forward butterfly."],"props":["pair of poi"],"commonMistakes":["Heads tangling at the top.","One wing drooping."]},"poi-chase-the-sun":{"name":"Chase the Sun","description":"Hands together in front and split timing: the two heads follow each other round one big circle, always half a turn apart.","goodFor":"Split timing with the hands close, ready for weaves.","alignmentCues":["One head always opposite the other.","Hands move as one."],"props":["pair of poi"],"commonMistakes":["Heads catching up with each other.","Hands separating."]},"poi-wheels":{"name":"Forward Wheels","description":"Both poi turning beside you like the wheels of a bicycle, the tops rolling forward.","goodFor":"The wheel plane, beside the body.","alignmentCues":["Circles run parallel to your sides.","Elbows soft and close."],"props":["pair of poi"],"commonMistakes":["Poi clipping the legs.","Wheels splaying outwards."]},"poi-reverse-wheels":{"name":"Backward Wheels","description":"Wheels rolling backwards beside you, the heads coming up in front and dropping behind.","goodFor":"Both directions in the wheel plane.","alignmentCues":["Same wheels, reversed.","Shoulders down and relaxed."],"props":["pair of poi"],"commonMistakes":["Wheels drifting behind the body.","Wrists stiffening."]},"poi-fountain":{"name":"Fountain","description":"Wheels in split time: one poi rises as the other falls, like water in a fountain beside you.","goodFor":"Split timing in the wheel plane, the base of the walking weave.","alignmentCues":["One up, one down.","Keep the rhythm even between hands."],"props":["pair of poi"],"commonMistakes":["Timing collapsing to same time.","Wheels angling inwards."]},"poi-opposite-wheels":{"name":"Opposite Wheels","description":"One wheel rolls forward while the other rolls back. The heads pass each other at the top and the bottom.","goodFor":"Coordination with the hands turning opposite ways.","alignmentCues":["Both reach the top together.","Each hand keeps its own direction."],"props":["pair of poi"],"commonMistakes":["Both hands switching to the same direction.","One wheel shrinking."]},"poi-overhead":{"name":"Overhead Floor Spin","description":"Both poi circling flat above your head like helicopter blades, hanging slightly lower at the outside as they turn.","goodFor":"The floor plane and steady shoulders overhead.","alignmentCues":["Hands just above the head.","Let the poi plane out; don’t muscle them."],"props":["pair of poi"],"commonMistakes":["Shoulders hunching.","Poi dipping in front."]},"poi-low-floor":{"name":"Hip-Height Floor Spin","description":"The floor plane brought down to the hips: the poi sweep round at waist height beside you.","goodFor":"The low floor plane used in floor-to-wall hybrids.","alignmentCues":["Hands out beside the hips.","Keep the circles level."],"props":["pair of poi"],"commonMistakes":["Poi hitting the thighs.","Leaning forward."]},"poi-three-beat-weave":{"name":"Three-Beat Weave","description":"The signature poi move: split-time poi swinging from one side of the body to the other, the arms crossing and uncrossing as the planes change sides.","goodFor":"The flow move every poi spinner builds from.","alignmentCues":["Turn the shoulders with the weave.","Planes tilt slightly towards each side."],"props":["pair of poi"],"commonMistakes":["Hands staying in the middle.","Poi hitting each other at the crossing."]},"poi-reverse-three-beat-weave":{"name":"Reverse Three-Beat Weave","description":"The three-beat weave with both poi spinning backwards. The arms cross over the top instead of underneath.","goodFor":"Weaving in both directions.","alignmentCues":["Same side-to-side pattern, reversed spin.","Keep the hands at chest height."],"props":["pair of poi"],"commonMistakes":["Heads clashing at the top.","Weave shrinking to one side."]},"poi-two-beat-weave":{"name":"Two-Beat Weave","description":"A faster weave that changes sides every beat. Quicker crossings make it busier and more compact.","goodFor":"Quick side changes.","alignmentCues":["Smaller, quicker shoulder turns.","Cross the wrists close to the chest."],"props":["pair of poi"],"commonMistakes":["Falling back into three-beat timing.","Losing the split."]},"poi-five-beat-weave":{"name":"Five-Beat Weave","description":"A longer, wider weave: the poi spend more turns on each side before they cross back.","goodFor":"Holding the weave shape over longer phrases.","alignmentCues":["Wide shoulder turns.","Keep the crossings smooth."],"props":["pair of poi"],"commonMistakes":["Crossing too early.","Planes flattening out."]},"poi-behind-back-weave":{"name":"Behind-the-Back Weave","description":"Every other pair of beats the right poi sweeps round behind your back and returns to the front without breaking time.","goodFor":"Body passes that change the look of a simple pattern.","alignmentCues":["Reach low behind the hips.","Look forward, trust the timing."],"props":["pair of poi"],"commonMistakes":["Poi hitting the back.","Front poi stopping while the back one travels."]},"poi-crossers":{"name":"Crossers","description":"Same-time wall spins while the arms cross in front of you and open again, the poi trading sides on every beat.","goodFor":"Arm crossings with the poi in time.","alignmentCues":["Cross at the wrists.","Keep both poi in step."],"props":["pair of poi"],"commonMistakes":["Tethers tangling as the arms cross.","One poi stalling."]},"poi-reels":{"name":"Reels","description":"Both poi spinning together on one side of the body for a bar, then swinging across to the other side.","goodFor":"Moving both poi as a unit around the body.","alignmentCues":["Hands stay close together.","Turn the body to face each side."],"props":["pair of poi"],"commonMistakes":["Hands separating as they cross.","Crossing off the beat."]},"poi-thread-the-needle":{"name":"Thread the Needle","description":"Opposite-direction, split-time poi with crossing arms: one poi slips through the gap the other has just left.","goodFor":"Precise timing between the two hands.","alignmentCues":["Cross when the gap opens.","Keep the circles tight."],"props":["pair of poi"],"commonMistakes":["Poi colliding mid-cross.","Timing slipping to same time."]},"poi-buzzsaw":{"name":"Buzzsaw","description":"Hands pressed together and both poi turning as one, the tethers side by side like a single spinning blade.","goodFor":"Matching the two poi exactly.","alignmentCues":["Palms together, wrists relaxed.","One circle, two heads."],"props":["pair of poi"],"commonMistakes":["Heads separating.","Hands drifting apart."]},"poi-one-hand-isolation":{"name":"One-Poi Isolation","description":"The hand circles opposite the head at the same speed, so the middle of the tether seems pinned in the air while the poi turns around it.","goodFor":"The first illusion: a fixed point in space.","alignmentCues":["Hand always opposite the head.","Watch the middle of the tether, not the head."],"props":["one poi"],"commonMistakes":["Hand circle too small, so the point wanders.","Speeding up at the top."]},"poi-isolation":{"name":"Isolations","description":"Isolations in both hands at once, the two still points side by side in front of you.","goodFor":"Two-hand illusion control.","alignmentCues":["Both hands opposite their heads.","Elbows soft, shoulders down."],"props":["pair of poi"],"commonMistakes":["One hand losing the isolation.","Points drifting forward."]},"poi-split-isolation":{"name":"Split-Time Isolations","description":"Isolations half a turn apart: one hand up while the other is down, the still points holding steady.","goodFor":"Isolation timing in split time.","alignmentCues":["Hands alternate top and bottom.","Points stay level with each other."],"props":["pair of poi"],"commonMistakes":["Hands syncing up.","Points sinking."]},"poi-wheel-isolation":{"name":"Wheel-Plane Isolations","description":"Isolations beside you in the wheel plane, still points hovering at your sides.","goodFor":"Isolations in a second plane.","alignmentCues":["Points level with the hips.","Hands circle parallel to your sides."],"props":["pair of poi"],"commonMistakes":["Planes twisting outwards.","Hands too close to the body."]},"poi-extension":{"name":"Extensions","description":"Arm and tether in one straight line, the hand circling wide so the poi traces the biggest possible circle.","goodFor":"Big, open shapes and the extension half of the cateye.","alignmentCues":["Reach from the shoulder.","Hand and head on one line from the centre."],"props":["pair of poi"],"commonMistakes":["Bending at the wrist.","Circles collapsing at the bottom."]},"poi-cateye":{"name":"Cateye","description":"One hand isolates while the other extends. The two paths overlap in an almond shape, like the eye of a cat.","goodFor":"Mixing two different hand paths at once.","alignmentCues":["Isolating hand tight, extending hand wide.","Both start at the top together."],"props":["pair of poi"],"commonMistakes":["Both hands doing the same thing.","Shape lopsided."]},"poi-one-hand-antispin":{"name":"One-Poi Antispin","description":"The hand circles one way while the poi spins the other, three spins to each hand circle, drawing a four-petal flower.","goodFor":"The antispin feel before flowers with two poi.","alignmentCues":["Hand circle wide and slow.","Each petal tip at the edge of the hand circle."],"props":["one poi"],"commonMistakes":["Poi flipping back into plain spin.","Petals uneven."]},"poi-antispin-flower":{"name":"Four-Petal Antispin","description":"Antispin flowers in both hands at once, two four-petal flowers blooming side by side.","goodFor":"The classic poi flower.","alignmentCues":["Hands circle together.","Petals line up: top, side, bottom, side."],"props":["pair of poi"],"commonMistakes":["One hand dropping into spin.","Flowers drifting forward."]},"poi-split-antispin":{"name":"Split-Time Antispin","description":"Four-petal flowers with the poi half a turn apart, the petals of one flower filling the gaps in the other.","goodFor":"Flower timing in split time.","alignmentCues":["Hands opposite each other on their circles.","Petals interleave."],"props":["pair of poi"],"commonMistakes":["Collapsing into same time.","Hands circling at different speeds."]},"poi-three-petal-antispin":{"name":"Three-Petal Antispin","description":"A three-petal flower: two antispins to each hand circle, giving a triangular bloom.","goodFor":"Changing petal counts by changing the hand speed.","alignmentCues":["Faster hand than the four-petal.","Petals at three evenly spaced points."],"props":["pair of poi"],"commonMistakes":["Slipping back to four petals.","Hand circle shrinking."]},"poi-five-petal-antispin":{"name":"Five-Petal Antispin","description":"Four antispins to each hand circle, a five-petal flower with a slower, wider hand.","goodFor":"Fine control of the hand-to-poi ratio.","alignmentCues":["Very slow hand.","Count four poi turns per hand circle."],"props":["pair of poi"],"commonMistakes":["Losing count of the petals.","Hand stopping."]},"poi-wheel-antispin":{"name":"Wheel-Plane Antispin","description":"Four-petal antispin flowers beside you in the wheel plane.","goodFor":"Flowers in the wheel plane.","alignmentCues":["Flowers parallel to your sides.","Hands circle beside the hips."],"props":["pair of poi"],"commonMistakes":["Planes angling inward.","Petals clipping the legs."]},"poi-overhead-antispin":{"name":"Overhead Antispin","description":"Antispin flowers flat above the head, the petals opening out over you.","goodFor":"Flowers in the floor plane.","alignmentCues":["Hands just above the head.","Petals stay level."],"props":["pair of poi"],"commonMistakes":["Flowers tipping forward.","Shoulders tiring and dropping."]},"poi-antispin-and-spin":{"name":"Antispin and Spin","description":"The right hand draws a four-petal antispin flower while the left keeps a plain forward spin.","goodFor":"Hand independence: two different shapes at once.","alignmentCues":["Spinning hand stays tight.","Flower hand circles wide."],"props":["pair of poi"],"commonMistakes":["Both hands copying each other.","Spinning poi slowing down."]},"poi-inspin-flower":{"name":"Four-Petal Inspin","description":"The hand circles slowly the same way as the poi, five spins to each hand circle, drawing loops that point inward.","goodFor":"Inspin flowers, the counterpart to antispin.","alignmentCues":["Hand and poi turn the same way.","Petal loops face the centre."],"props":["pair of poi"],"commonMistakes":["Hand circle too fast.","Loops uneven."]},"poi-three-petal-inspin":{"name":"Three-Petal Inspin","description":"Inspin with four spins to each hand circle, drawing a three-looped flower.","goodFor":"Changing inspin petal counts.","alignmentCues":["Slightly faster hand than four petals.","Three loops, evenly spaced."],"props":["pair of poi"],"commonMistakes":["Counting wrong.","Loops flattening."]},"poi-wall-wheel-hybrid":{"name":"Wall–Wheel Hybrid","description":"Each revolution the poi swap planes, front then side, turning as the head passes straight down.","goodFor":"Changing planes without breaking the spin.","alignmentCues":["Switch as the poi points at the floor.","Turn the wrist, not the whole arm."],"props":["pair of poi"],"commonMistakes":["Switching mid-circle.","Poi wobbling between planes."]},"poi-wheel-floor-hybrid":{"name":"Wheel–Floor Hybrid","description":"The poi alternate between turning beside you and sweeping flat, changing as they point forward.","goodFor":"A second hybrid with a horizontal plane.","alignmentCues":["Switch as the poi points ahead.","Keep the hands at hip height."],"props":["pair of poi"],"commonMistakes":["Poi dipping during the change.","Losing the beat."]},"poi-floor-wall-hybrid":{"name":"Floor–Wall Hybrid","description":"From flat overhead to upright in front and back again, changing as the poi point out to the sides.","goodFor":"Linking overhead and wall planes.","alignmentCues":["Change when the poi point sideways.","Raise and lower the hands smoothly."],"props":["pair of poi"],"commonMistakes":["Poi hitting the head.","Uneven switches."]},"poi-top-stall":{"name":"Stall","description":"The poi rises to the top, pauses for an instant straight above the hand, and falls back the way it came.","goodFor":"Stopping and reversing: the basis of stall combos and hyperloops.","alignmentCues":["Lift the hand as the poi peaks.","Let it hang, then guide it back."],"props":["one poi"],"commonMistakes":["Tether going slack and wrapping.","Rushing the pause."]},"poi-stalls":{"name":"Double Stalls","description":"Both poi stall together at the top and reverse, side by side.","goodFor":"Two-hand stall control.","alignmentCues":["Both peak at the same moment.","Hands lift together."],"props":["pair of poi"],"commonMistakes":["One poi stalling late.","Poi clashing on the way down."]},"poi-side-stall":{"name":"Side Stalls","description":"The poi stall out at the sides instead of the top, each one pausing level with the shoulder before swinging back.","goodFor":"Stalls at a different point of the circle.","alignmentCues":["Pause as the poi points out sideways.","Arms soft."],"props":["pair of poi"],"commonMistakes":["Poi dropping instead of pausing.","Timing drifting."]},"poi-chasing-stalls":{"name":"Chasing Stalls","description":"Stalls half a beat apart: one poi pauses at the top while the other is still on its way up.","goodFor":"Stalls in split time.","alignmentCues":["One stall, then the other.","Keep the hands at chest height."],"props":["pair of poi"],"commonMistakes":["Both stalling together.","Rushing the second stall."]},"poi-hyperloop":{"name":"Hyperloop","description":"A stall where the plane flips over at the top, so the poi loops round and comes down on the other face of the circle.","goodFor":"Three-dimensional loops from the stall.","alignmentCues":["Turn the wrist at the top of the stall.","Keep the tether taut."],"props":["one poi"],"commonMistakes":["Flipping before the poi peaks.","Tether slackening."]},"poi-arm-wrap":{"name":"Arm Wrap","description":"The poi winds round the other forearm held out in front, spinning faster on a shorter tether, then unwinds back to a full circle.","goodFor":"The first wrap, and how wraps speed the poi up.","alignmentCues":["Hold the post arm still and level.","Keep the spinning hand behind the post."],"props":["one poi"],"commonMistakes":["Post arm moving.","Unwinding the wrong way."]},"poi-leg-wrap":{"name":"Leg Wrap","description":"Lift the knee and let the poi wrap round the thigh, then lower the leg as it unwinds.","goodFor":"Wraps on the body.","alignmentCues":["Knee up as the poi arrives.","Stay tall on the standing leg."],"props":["one poi"],"commonMistakes":["Lifting the knee late.","Losing balance."]},"poi-neck-wrap":{"name":"Neck Wrap","description":"From an overhead spin, bring the hand down so the poi wraps round the back of the neck and unwinds back overhead.","goodFor":"A showy wrap that links overhead spins.","avoidIf":["Use practice poi with soft heads; never learn neck wraps with fire."],"alignmentCues":["Chin level, neck long.","Guide the tether to the base of the neck."],"props":["one poi"],"commonMistakes":["Wrapping at the head.","Tether too slack."]},"poi-cord-wrap":{"name":"Tether Wrap","description":"From a butterfly, the two tethers wrap round each other at the bottom, the heads whirling on short cords before they unwind.","goodFor":"Wraps between the two poi.","alignmentCues":["Meet the tethers at the bottom of the butterfly.","Keep the hands still while they wrap."],"props":["pair of poi"],"commonMistakes":["Hands pulling apart.","Wrap tangling."]},"poi-toss":{"name":"Poi Toss","description":"Let go of the handle as the poi swings up. It spins through the air and you catch the handle as it comes back round.","goodFor":"Releases and catches.","avoidIf":["Practise tosses with soft poi and space around you."],"alignmentCues":["Release on the upswing.","Watch the handle, not the head."],"props":["one poi"],"commonMistakes":["Releasing too late.","Grabbing the tether instead of the handle."]},"poi-high-toss":{"name":"High Toss","description":"A higher toss with an extra turn in the air before the catch.","goodFor":"Bigger tosses with more spin.","alignmentCues":["A firmer push on release.","Catch as the handle comes round."],"props":["one poi"],"commonMistakes":["Toss drifting forward.","Snatching at the catch."]},"poi-double-toss":{"name":"Double Toss","description":"Both poi tossed in split time, one after the other, and caught back into the spin.","goodFor":"Two-hand toss timing.","alignmentCues":["Release one, then the other.","Catch in the same order."],"props":["pair of poi"],"commonMistakes":["Releasing both together.","Watching one poi and losing the other."]},"shake-out":{"name":"Shake Out","description":"Put the props down and shake out the hands and forearms. Let the shoulders drop.","goodFor":"A short reset between hard runs."},"breathe":{"name":"Rest and Reset","description":"Put the props down, stand easy and let the arms hang loose. Take a moment before the next run.","goodFor":"Lowers the heart rate and clears frustration after drops."}}`),r={"warmup-mobility":{name:`Flow warm-up`,description:`Wrists, shoulders, spine and hips loosened to a steady beat. Use it before any prop session.`,focus:`Warm-up · mobility`},"first-throws":{name:`First throws`,description:`One ball arcing hand to hand at eye height, then the two-ball exchange that every pattern grows from.`,focus:`Juggling · foundations`},"cascade-builder":{name:`Cascade builder`,description:`Two-ball exchanges back to back until the third ball joins: short cascade runs, reset, run again.`,focus:`Juggling · foundations`},"juggling-tempo-ladder":{name:`Cascade tempo ladder`,description:`The cascade at three tempos, a few beats faster each rung. Lower throws for the fast rungs.`,focus:`Juggling · tempo`},"siteswap-sampler":{name:`Siteswap sampler`,description:`Cascade into 423, 441 and 531, with the reverse cascade and shower as palate cleansers. Every pattern starts and ends in the cascade.`,focus:`Juggling · patterns`},"four-ball-session":{name:`Four-ball session`,description:`Two in one hand for each side, the four-ball fountain, then the synchronous fountain.`,focus:`Juggling · numbers`},"juggling-combo-flow":{name:`Juggling combo flow`,description:`A long flowing set: cascade, reverse cascade, Mills mess and the siteswaps strung into one piece of music.`,focus:`Juggling · combos`},"cascade-tricks":{name:`Cascade tricks`,description:`Tennis, half shower and claws, each one dropped into a running cascade and back out again.`,focus:`Juggling · variations`},"juggling-body-throws":{name:`Body throws`,description:`Under the leg, behind the back, chops and penguins: the cascade thrown around the body.`,focus:`Juggling · body throws`},"sync-shapes":{name:`Sync shapes`,description:`Columns, the rainbow cross, the box and the yo-yo: three balls thrown two at a time.`,focus:`Juggling · sync patterns`},"club-foundations":{name:`Club foundations`,description:`Single spins, the two-club exchange and the three-club cascade, with flats to finish.`,focus:`Juggling · clubs`},"passing-with-a-partner":{name:`Passing with a partner`,description:`Face your partner and pass: one ball across, then two each, then the six-count, four-count and two-count.`,focus:`Juggling · passing`},"club-passing-session":{name:`Club passing`,description:`Club four-count to warm up, two-count and three-count for rhythm, then double passes.`,focus:`Juggling · club passing`},"hoop-juggling-session":{name:`Hoop juggling`,description:`Full-size hoops thrown edge on: single tosses, the exchange, the cascade and its reverse.`,focus:`Juggling · hoops`},"staff-first-spins":{name:`First staff spins`,description:`The wheel spin beside the body, then the front spin. Slow, even turns, one per beat.`,focus:`Staff · foundations`},"staff-foundations":{name:`Staff foundations`,description:`Wheel spin, front spin, figure 8 and the hand-to-hand pass-through linked on the beat.`,focus:`Staff · foundations`},"staff-flow-weave":{name:`Staff flow weave`,description:`Figure 8 into butterfly, one-hand spins and the helicopter, joined so the staff never stops.`,focus:`Staff · flow`},"staff-isolation-lab":{name:`Staff isolation lab`,description:`Isolations and the antispin flower at a slower tempo, with behind-the-back passes between.`,focus:`Staff · technical`},"staff-advanced-flow":{name:`Staff advanced flow`,description:`The full vocabulary in one long piece: weaves, wraps, isolations and the neck roll.`,focus:`Staff · flow`},"staff-both-ways":{name:`Staff both ways`,description:`Every foundation spin forwards then in reverse, plus the two-hand helicopter overhead.`,focus:`Staff · direction and planes`},"staff-contact-lab":{name:`Staff contact lab`,description:`Open-hand and body contact: fishtails, the steering wheel, hand and forearm rolls, and a toss to finish.`,focus:`Staff · contact`},"double-staff-session":{name:`Double staff session`,description:`A short staff in each hand: same time, split time, wheels and split wheels.`,focus:`Staff · double staff`},"hoop-first-spins":{name:`First hoop spins`,description:`Waist hooping with a front-back push, then spinning the hoop around one hand.`,focus:`Hoop · foundations`},"hoop-body-flow":{name:`Hoop on-body flow`,description:`Moving the hoop up to the chest and down to the knees and back to the waist, without stopping.`,focus:`Hoop · on-body`},"hoop-off-body":{name:`Off-body hoop`,description:`Hand spins, lasso, wedgies and passes, finishing with isolations that hold the hoop still in space.`,focus:`Hoop · off-body`},"hoop-full-flow":{name:`Hoop full flow`,description:`On-body and off-body together: escalators, neck hooping and the off-body tricks in one long flow.`,focus:`Hoop · flow`},"hoop-body-zones":{name:`Hoop body zones`,description:`Waist both ways, then hips, thighs and chest, lifting and dropping the hoop between zones.`,focus:`Hoop · on body`},"hoop-tricks-session":{name:`Hoop tricks`,description:`Side spins, the coin flip, the weave, a toss and the drop-in back onto the body.`,focus:`Hoop · off body`},"hoop-doubles-session":{name:`Hoop doubles`,description:`Two hoops: mirrored and offset hand spins, side spins, and a waist hoop with a hand spin.`,focus:`Hoop · doubles`},"poi-foundations":{name:`Poi foundations`,description:`One poi, then two: forward and backward wall spins, wheels beside you, split time and the butterfly.`,focus:`Poi · first spins`},"poi-weave-session":{name:`Poi weaves`,description:`Split time into the three-beat weave, both directions, then the two-beat weave, reels and crossers.`,focus:`Poi · weaves`},"poi-flower-lab":{name:`Poi flower lab`,description:`Extensions and isolations, then antispin with one poi and two, and an inspin flower to finish.`,focus:`Poi · flowers`},"daily-mixed-flow":{name:`Daily mixed flow`,description:`A little of each art: cascade, staff spins and hooping, with a mobility move between props.`,focus:`Mixed · practice`}},i=JSON.parse(`{"start-here":{"title":"Start here: your first week of flow","summary":"Pick one prop, practise ten minutes a day on the beat, and let the unlock tree tell you what comes next.","imageAlt":"3D figure tossing a single juggling ball from hand to hand","body":["Flow arts look like magic from the outside: balls hanging in the air, a staff turning into a blur, a hoop orbiting a dancer who barely seems to move. From the inside they are a stack of very small skills, each one learnable in an afternoon, layered until the stack looks effortless. Your first week is about the bottom of that stack.","Choose one prop to start. Juggling teaches timing and hand–eye coordination; staff teaches planes and smooth hand changes; hoop teaches rhythm through the whole body. You can learn all three, but one at a time keeps your attention where the progress is. The Rewards tree shows every movement for each art, from the first throw or spin to advanced patterns, and opens the next ones when you master what they build on.","Practise little and often. Ten focused minutes a day beats an hour on Sunday, because coordination is consolidated between sessions, especially during sleep. A short routine from the Routines page, a warm-up, and a few counted steps of your current movement is a complete practice.","Practise on the beat from day one. Every movement in SynthFlow is counted in bars at a tempo, with music or generated percussion that matches. The beat gives you something to hold on to when the prop does not cooperate, and it makes progress measurable: a clean run at 90 BPM this week, 100 next week.","Expect drops. Everyone drops, including professionals in rehearsal. A drop tells you which throw or catch needs attention; it says nothing about talent. Pick the prop up, wait for the next downbeat, and go again. By the end of the week you will have a movement you can do without thinking, and that is the moment flow begins."]},"counting-and-the-beat":{"title":"Counts, bars and the beat","summary":"Why every movement is counted in bars at a tempo, and how to lock your throws and spins onto the music.","imageAlt":"3D figure juggling a three-ball cascade with arcs drawn above the hands","body":["Music is made of beats grouped into bars, usually four beats to a bar. Flow movements are made of cycles: a throw from each hand, a half turn of the staff, one orbit of the hoop. When a cycle lands on the beat, the movement and the music become one thing. That is why SynthFlow measures every routine step in bars rather than seconds, and why each movement says how many beats one cycle takes.","In a three-ball cascade each throw falls on a beat, alternating right and left. In a staff front spin one half turn usually takes a beat. Hooping at the waist is commonly one orbit per beat at a relaxed tempo. The counts in the player name what happens on each beat, and the 3D figure moves exactly on the same clock as the audio, so you can copy it in time.","Tempo is measured in beats per minute (BPM). Each movement has a comfortable range: slow enough to stay clean, fast enough that the prop keeps its momentum. Below the range spinning props stall and throws go so high they drift; above it you start to rush and drop. The builder warns you when a step sits outside its movement’s range.","Start each step on the downbeat, the “one” of the bar. The count-in gives you a bar to get the prop moving before the counted bars begin. If you lose the beat, do not chase it: stop, listen for the next “one”, and come back in. Musicians call this finding the top of the bar, and it works for flow artists too.","Counting aloud for a few sessions helps more than it seems to. Saying “one, two, three, four” while you juggle ties the rhythm to your breath and voice, so it survives when the pattern gets hard. Spoken counts start off; turn them on under Settings → Voice & music when you want them, then turn them off again and let the music carry you."]},"tempo-ladders":{"title":"Tempo ladders: slow is smooth, smooth is fast","summary":"Climb a few BPM at a time from a tempo you can do cleanly, and step back down the moment form breaks.","imageAlt":"3D figure spinning a staff in front of the body in the wall plane","body":["A tempo ladder is the same movement repeated at rising tempos: eight bars at 80 BPM, eight at 88, eight at 96, and so on. It is the most reliable way to make a movement faster without making it messier, and several built-in routines are built around it.","Start on a rung you can do cleanly, even if it feels too easy. The point of the bottom rung is not challenge; it is rehearsing correct form so that form is what speeds up. Step up by a small amount, around five to ten percent. Big jumps change the movement: throws get lower, spins get shallower, and you end up practising a different trick.","Stop climbing when form breaks, not when you drop. Watch for the early signs: peaks getting uneven, the staff drifting out of its plane, the hoop riding up or down. Those are the cues to step back a rung and run it again. Finishing a ladder on a clean run at a tempo just below your limit teaches your body that tempo; finishing on a crash teaches the crash.","Slow tempos are harder than they look for spinning props, because the prop has less momentum to carry it through. If a staff or hoop stalls at the bottom of its range, keep the tempo and enlarge the movement slightly, or take it in half time with the music: one cycle every two beats.","Track your top clean tempo for each movement in Progress. Seeing that number creep up over weeks is good motivation, and it also shows when a movement has plateaued and needs a different drill rather than more of the same."]},"siteswap-notation":{"title":"Siteswap: juggling written as numbers","summary":"Each number is how many beats later a ball is thrown again; odd numbers cross, even numbers stay, and the average is the ball count.","imageAlt":"3D figure juggling the siteswap 441 with two high throws and a quick zip","body":["Juggling patterns are hard to describe in words and easy to describe in numbers. Siteswap, developed independently in the mid-1980s by jugglers in Cambridge, at Caltech and in Santa Cruz, writes a pattern as a repeating sequence of digits. It is how jugglers share patterns, check whether an idea can work, and discover tricks nobody has tried. SynthFlow uses it to animate every juggling pattern from the same engine.","Imagine the hands throwing alternately on every beat: right, left, right, left. Each digit in a siteswap says how many beats from now the ball thrown on this beat will be thrown again. A 3 comes back three beats later; because three is odd, it lands in the other hand. A three-ball cascade is just 3, 3, 3, 3 forever, written simply as 3. A 4 comes back four beats later in the same hand, which is the four-ball fountain.","Small numbers have special meanings. A 2 returns to the same hand two beats later, which in practice means holding the ball for a moment. A 1 crosses to the other hand on the very next beat, a quick zip straight across. A 0 is an empty hand. Bigger numbers are higher throws: a 5 is a tall crossing throw.","Read a pattern digit by digit. In 441, two throws stay on their own side while a third ball zips across underneath them. In 531, a high crossing throw goes up while a cascade throw and a zip keep the other two balls moving. In 423, a fountain-height throw, a held ball and a cascade throw take turns.","The average theorem tells you how many balls a pattern needs: add the digits and divide by how many there are. 441 adds to 9 over three digits, so three balls. If the average is not a whole number, the sequence cannot be juggled. A second check is that no two balls may land in the same hand on the same beat, which is how jugglers spot impossible patterns before trying them.","Siteswap also has notation for both hands throwing together, written in brackets such as (4,4), and for throwing two balls from one hand at once, written in square brackets. You do not need any of this to juggle well, but once the numbers click, every new pattern name starts explaining itself. Open the Flow glossary for the individual numbers."]},"passing-basics":{"title":"Passing basics: juggling with a partner","summary":"Face a partner, throw right hands together, pass straight across to their left hand, and count: six-count, four-count, two-count.","imageAlt":"Two 3D jugglers facing each other, passing balls straight across between them","body":["Passing is juggling with someone else. Two jugglers stand face to face, each running a cascade, and every so often one of the throws goes across to the partner instead of to yourself. It is one of the most social things in juggling: club passing is how many jugglers spend a festival evening, and it turns practice into a conversation.","Stand about two and a half metres apart for balls, a little further for clubs. Both of you start juggling on the same count, right hands throwing together. The standard pass is straight: it leaves your right hand and lands in your partner’s left hand, directly opposite you. It is not thrown at their face. Aim at their left hip and give it an arc that peaks just above head height, halfway between you.","Passing patterns are named by how often you pass. In a six-count you pass every sixth throw, which leaves five selfs in between to settle. In a four-count, the standard warm-up, you pass on every other right-hand throw: pass, self, self, self. In a two-count every right-hand throw is a pass and every left is a self. In a three-count the passes alternate hands, so you learn to pass from the left too. Ultimates, or a one-count, makes every single throw a pass.","Count out loud together at first. “Pass, two, three, four” keeps you on the same beat, and the moment one of you drifts the passes stop arriving on time. SynthFlow’s count voice says “pass” on your passes and “self” on the other throws on the beat, so you can practise the timing alone while the partner on screen juggles with you.","Start with one ball. Throw it across, let your partner hand it from their left to their right and throw it back. Then take two balls each and pass right hands together, handing the incoming ball across from left to right. Only then add the cascade. Most passing drops come from passes that are too long or too flat, and both are easier to fix with one ball than with six.","In SynthFlow notation a passing pattern lists your throws and your partner’s, one per beat, with p marking a pass: the four-count is <3p 3 3 3|3p 3 3 3>. The numbers mean the same as in siteswap. A 4p is a double pass that lands a beat later, which is how seven-club patterns are built."]},"planes-and-geometry":{"title":"Planes: wall, wheel and floor","summary":"Spinning props live in flat planes; keeping the plane clean is most of what makes a staff or hoop look crisp.","imageAlt":"3D figure weaving a staff in a figure-8 on both sides of the body","body":["A spinning staff or hoop sweeps out a flat surface, called its plane. Flow artists describe three basic planes relative to the body. The wall plane is in front of you, like a pane of glass you could press your palms against. The wheel plane is beside you, the way a cart wheel turns along your side. The floor plane is horizontal, parallel to the ground, as in an overhead helicopter or a lasso.","Clean planes are what audiences read as skill. A staff that wobbles out of its plane looks uncertain even if it never drops; a hoop that stays perfectly flat during a pass looks effortless. Most early practice is quietly about planes: keeping the wrists from twisting, keeping the elbows from flaring, and letting the shoulders move the prop rather than the hands.","Many tricks are defined by changing planes. A figure-8 weave moves the staff from the wheel plane on one side to the wheel plane on the other. A butterfly folds it behind the shoulder and back. An escalator walks a hoop up and down the body while its plane stays level. Learning where each movement starts and ends in space is how you link them into flow.","The 3D viewer can draw the plane while you practise. Turn it on when learning a new spin and compare: is your staff tilting toward you at the top? Is the hoop dipping at the front? A mirror or a phone camera shows the same thing. Watching from the side view is especially useful for wall-plane moves, because tilt is invisible from the front.","Planes also help with safety and space. Before a session, check that each plane you will use is clear: the wall in front, the walls beside you, and the ceiling above for floor-plane and overhead moves. A clean plane with nothing in it is a confident plane."]},"spin-and-antispin":{"title":"Spin, antispin and isolations","summary":"How the prop turns compared with the hand gives three families of movement: spin, antispin and isolation.","imageAlt":"3D figure drawing a four-petal antispin flower with a staff","body":["When you move a spinning prop around in a circle, two rotations happen at once: your hand travels around a circle, and the prop turns around its own centre. Flow theory names movements by how those two rotations relate. It is the same vocabulary for staff, hoop and poi, which is why skills transfer between props so well.","In spin, sometimes called inspin, the prop turns the same way as the hand’s circle. This is the natural direction; most first spins are inspin without anyone calling them that. The traced shape is a flower whose petals point outward.","In antispin the prop turns the opposite way to the hand’s circle. It feels strange at first, like patting your head and rubbing your belly, but it draws the classic petal flower. The number of petals depends on how many times the prop turns for each hand circle: three counter-rotations per circle gives four petals, which is the Four-Petal Antispin in the staff tree.","An isolation is the special case where the hand circles so that one point of the prop appears frozen in space. With a staff the centre stays still while the ends sweep around it; with a hoop the centre of the ring or one point on the rim stays put. Isolations look like the prop is floating and the body is orbiting it. They demand precise hand paths, which makes them excellent training for every other trick.","Learn these slowly and to the beat. Antispin especially benefits from a tempo well below your normal spinning speed, with counts that name where the prop should be: top, side, bottom, side. Use the ghost in the 3D viewer to see the next beat’s position, and the trail to see whether your flower has even petals.","Once spin, antispin and isolation feel familiar in one plane, try them in another. The theory stays the same and your body learns that the plane is just a setting, which is a big step toward improvising flow."]},"sequencing":{"title":"How flow routines are built","summary":"Warm up, practise one focus with links that flow on, keep tempo jumps small, and finish with an easy cool-down.","imageAlt":"3D figure passing a hoop from hand to hand in front of the body","body":["A good flow routine has the same shape as a good music set: an opening that warms the room, a middle that builds, and an ending that lets everyone breathe. SynthFlow’s built-in routines follow that shape, and the builder’s co-pilot checks yours against it.","Open with a warm-up. Wrist circles, arm circles and shoulder rolls take the joints you will load through their range at a gentle tempo. Two or three minutes is enough for a short session; longer sessions and cold days deserve more.","Give the practice block one focus. Pick a movement you are working on and surround it with movements that link into it. The builder shows how each step connects to the one before: flowing straight on from the same hand position, a small re-grip, setting the prop down, or building on an earlier trick. Routines that flow on feel like dancing; routines full of set-downs feel like a list.","Keep tempo changes small between steps. Jumping from 80 to 130 BPM resets your timing and invites drops. The co-pilot flags jumps of more than about a quarter, folding half and double time so a 70 BPM hoop step can sit next to a 140 BPM track.","Return to the focus movement more than once. Repetition across a session, with other movements in between, builds skill better than one long block, because each return is a fresh attempt from a slightly different starting point.","Finish with a cool-down: an easy movement at a slow tempo, or a short rest with a few breaths. It brings the heart rate down and gives your coordination a calm ending to remember. Preview the routine before playing it and remove anything that is clearly yesterday’s ambition."]},"effort":{"title":"When to push the tempo","summary":"Push when form holds and you are fresh; ease off when peaks wobble, grip tightens or drops start clustering.","imageAlt":"3D figure juggling five balls in a tall cascade","body":["Progress in flow comes from practising at the edge of your ability, but the edge moves. Some days it is further out than you expect; some days it has retreated. Learning to read it is a skill worth as much as any trick.","Push when the basics hold. If your peaks are even, your staff stays in its plane, your hoop stays level and your breathing is easy, take the next rung of the tempo ladder or try the next drill on the progression. The first fifteen minutes of a session, after a warm-up, are usually the best time for new material.","Ease off when quality slips. Clustered drops, a tightening grip, shoulders creeping toward your ears and a held breath all say that your nervous system is tired. Drop the tempo, go back to a movement you own, or end the session. Pushing through fatigue mostly rehearses mistakes.","Watch for physical warnings too. Repetitive throwing and spinning load the wrists, forearms and shoulders. Aching that fades within a day is normal adaptation. Sharp pain, pain that grows during practice, numbness or tingling are reasons to stop and rest; persistent symptoms deserve a clinician.","Use the effort rating after each session. The practice wizard reads it: several hard sessions in a row and it suggests something gentler, several easy ones and it suggests a little more. Honest ratings make better suggestions."]},"drops-are-data":{"title":"Drops are data","summary":"A drop tells you which throw or catch to fix; treating it as failure only teaches you to tense up.","imageAlt":"3D figure exchanging two juggling balls between the hands","body":["Every juggler has a floor covered in balls at some point. Every staff spinner has heard the clatter. The difference between people who keep improving and people who quit is rarely talent; it is how they treat the drop.","A drop is a measurement. It tells you which throw went wrong, which catch you reached for, which moment of the spin lost its plane. If the same ball keeps landing in front of you, your throws are drifting forward. If drops come after six throws, something in your third or fourth throw is off. Watch where and when, then pick one thing to change.","Treating drops as failure has a cost. Fear tightens the shoulders and shortens the breath, and tension makes movements smaller and faster, which causes more drops. The calm response — pick up, breathe, wait for the downbeat, restart — is not just pleasant; it is the technically correct response.","Count clean runs, not drops. SynthFlow masters a movement when you have enough clean runs and practice minutes, so drops along the way are simply part of the minutes. Some days you will log ten clean runs, some days two. Both days count.","Drop on purpose sometimes. When learning a new trick, practise the first throw or the first half spin and let it fall. Then add the catch. Isolating the risky moment shrinks it, and you learn that the floor is not your enemy. It is just where the prop goes when you are learning."]},"safety":{"title":"Safety: space, props and red flags","summary":"Clear your planes, choose forgiving props, warm up, and stop for sharp pain, numbness or dizziness.","imageAlt":"3D figure spinning a staff flat overhead with clear space around","body":["Flow arts are low risk compared with most sports, but props move fast and travel further than you expect. A few habits keep practice safe for you, the people near you and the furniture.","Clear your space before you start. Check each plane you will use: in front, to the sides and above. Staff and hoop need more room than you think, usually a circle of at least arm span plus prop length in every direction, with nothing breakable within reach. Indoors, watch ceiling lights and fans; outdoors, watch uneven ground and passers-by.","Use forgiving props while learning. Beanbag juggling balls do not roll away. Padded or foam-ended staffs hurt less when they hit your head, which they will. A larger, heavier hoop turns more slowly and is easier to keep up. Upgrade to faster or flashier props once the basics are automatic.","Warm up before every session and build volume gradually. Throwing and spinning are repetitive, and repetitive load on cold tissue is the usual cause of sore wrists and elbows. If you add a lot of practice suddenly, add rest days too.","Stop for red flags: sharp or electric pain, numbness or tingling in the hands, pain that gets worse as you continue, dizziness, or a hit to the head with any lingering symptoms. Neck moves and contact rolls deserve extra care; learn them slowly with a padded prop.","This app teaches technique, not medical care. Pregnancy, recent injuries, joint conditions and anything that worries you are reasons to ask a qualified professional before adding new load. Fire performance is a separate discipline with its own safety training; SynthFlow does not teach it."]},"warm-up":{"title":"Why warm-ups matter for prop work","summary":"Two to five minutes of wrist, arm, shoulder and hip mobility make spins smoother and save your joints.","imageAlt":"3D figure doing slow wrist circles with arms forward","body":["Flow practice looks gentle, but it asks a lot of a few joints. Juggling repeats the same throw thousands of times; staff spinning rolls the wrists through their full range; hooping rocks the spine and hips on every orbit. Warm tissue tolerates that repetition far better than cold tissue.","A good flow warm-up is short and specific. Wrist circles in both directions prepare the joints that do most of the work. Arm circles and shoulder rolls wake up the rotator cuff and shoulder blades, which control the plane of every spin. Hip circles and torso twists matter most for hooping. Neck half circles, never full rolls, ease tension from staring up at a pattern.","Move slowly and to the beat. The warm-up steps in SynthFlow are counted like everything else, at a relaxed tempo, so the first few minutes of a session also tune your timing. By the time the props come out, you are already moving with the music.","Finish the warm-up with the prop at half speed. A few slow throws, a lazy front spin or a big slow hoop orbit link the mobility work to the movement you are about to practise, and they tell you how your body feels today.","Warm-ups are also a mental transition. The same three minutes at the start of every session become a cue that practice has begun. On busy days, the warm-up is sometimes the whole practice, and that still counts."]},"anatomy-basics":{"title":"The body behind the props","summary":"Forearms grip and release, shoulders steer the plane, the core keeps you still: a plain-English map for flow.","imageAlt":"3D figure hooping at the waist with a relaxed upper body","body":["You do not need to know anatomy to juggle, but a simple map helps you understand what tires, what to warm up and what to rest. The Muscles section of Learn has an interactive model; this article is the short tour.","The forearms do most of the fine work. Muscles on the palm side close the fingers and flex the wrist; muscles on the back of the forearm open the fingers and extend the wrist. Catching and releasing, gripping a staff and letting it roll, all happen here. Forearm fatigue is the most common feeling after a long session, and it is why relaxed grip is such a frequent cue.","The shoulders steer. The deltoids lift the arms; the rotator cuff, four small muscles around the joint, keeps the upper arm centred while it moves. Muscles around the shoulder blades hold the whole system steady. When a staff drifts out of its plane, the cause is often the shoulder, not the hand.","The core keeps you quiet. In juggling, a still torso keeps the pattern from wandering. In hooping, the abdominal and back muscles drive the hoop with small forward-and-back pulses. The hips and legs are your base: soft knees absorb movement and let you shift weight without disturbing the prop.","Your eyes and inner ear matter too. Juggling trains you to watch the peaks, not the hands; spinning trains your balance. Short sessions with rests let both adapt without dizziness. Treat this map as literacy, not diagnosis, and see a professional for pain that does not settle."]},"biomechanics-safety":{"title":"Wrists, shoulders and repetitive load","summary":"Relaxed grip, neutral wrists and gradual volume keep the joints that do all the work happy.","imageAlt":"3D figure spinning a staff with one hand over the back of the hand","body":["Flow injuries are rarely dramatic. They are almost always overuse: too many repetitions, too much grip, too little rest. The good news is that the same few habits prevent most of them.","Relax the grip. A juggling ball needs only enough pressure to stay in the hand; a staff needs a loose ring of fingers it can roll inside. Squeezing tires the forearm muscles and loads the tendons at the elbow. If your knuckles whiten or your forearms burn after a few minutes, loosen up and lower the tempo.","Keep wrists close to neutral when you can. Spinning takes the wrists through big ranges, which is fine in moderation. Holding them at the end of their range for long stretches, or forcing a stiff wrist to turn, is what irritates them. Let the elbow and shoulder share the movement.","Let the shoulders work, but not hunch. Big circles come from the shoulder joint; a shrugged shoulder pinches and tires quickly. Check in the mirror or the camera mode that your shoulders stay down, especially in overhead movements like the helicopter and lasso.","Build volume gradually. If you usually practise twenty minutes, do not jump to two hours because a festival is coming. Increase total time by a modest amount each week and keep at least one easy day. Swap props to spread the load: hoop work rests the forearms that juggling tires.","Pain that fades within a day is normal adaptation; pain that lingers, grows, or comes with numbness is not. Rest, reduce volume and seek professional advice if it persists. This is education, not medical advice."]},"choosing-props":{"title":"Choosing your first props","summary":"Beanbags for juggling, a light padded staff and a large adult hoop make the first weeks far easier.","imageAlt":"3D figure spinning a hoop around one hand","body":["Good beginner props make learning faster and less frustrating. You do not need expensive gear, but a few choices matter.","For juggling, start with three beanbag balls of about 60 to 130 grams each. Beanbags do not bounce or roll away when dropped, which saves a lot of chasing. They should fit comfortably in your palm. Stage balls, which are larger, and bouncy silicone balls are for later. Matching colours help you see the pattern; three different colours help you track individual balls when learning siteswaps.","For staff, a beginner spin staff is usually somewhere around 1.2 to 1.5 metres, light, with padded or rubber ends. As a rough guide it should reach between your chest and shoulder when stood on end. A longer, heavier staff turns more slowly and smoothly once you have the basics, but it is harder to start with and hurts more when it hits you. A grip in the middle helps.","For hoop, start bigger and heavier than you think. An adult beginner hoop typically reaches somewhere between the waist and chest when stood on the floor. Larger hoops rotate more slowly, giving you time to find the rhythm for waist hooping. Smaller, lighter hoops suit fast off-body tricks once you are comfortable.","Whatever you choose, make sure the movement’s tempo range suits the prop. Heavier props usually like lower tempos. If the app’s comfortable range feels rushed with your prop, set your own tempo in the builder; the counts follow."]},"practice-at-home":{"title":"Practising at home and in the park","summary":"Short daily sessions, a clear space, a bed or sofa edge to catch drops, and a park jam when you can.","imageAlt":"3D figure shaking out the arms between practice rounds","body":["Most flow artists learn at home, a few minutes at a time. A little set-up makes home practice easier to start and easier to keep.","Find your spot. For juggling, standing in front of a bed or sofa means dropped balls land at waist height instead of rolling under furniture, and it also stops you walking forward. For staff and hoop, find the largest clear space you have, check the ceiling, and move anything breakable. A garden or park is better for big spins.","Keep the props visible. Balls on the desk get juggled during calls and kettle breaks; a hoop by the door gets used. The less effort it takes to start, the more often you will. A five-minute routine counts, and several short sessions a day add up quickly.","Use the app as the structure. Pick a routine or let the wizard suggest one, play it through, and log your effort. Short programs like Zero to Cascade give each week a clear goal, which keeps you from drifting between tricks.","Practise with others when you can. Juggling clubs, circus schools and park flow jams exist in many cities. Watching someone a step ahead of you often fixes something a tutorial could not, and teaching someone a step behind you makes your own technique clearer. Bring your props, ask what people are working on, and share what the counts have taught you."]},"learning-with-the-app":{"title":"Learning with the 3D coach","summary":"Slow it down, mirror it, turn on the ghost and trails, change the camera, and use the camera mode for feedback.","imageAlt":"3D figure performing a staff isolation with a trail showing the path","body":["Every movement in SynthFlow is animated in 3D from the same clock as the music, so the figure is always exactly on the beat. Used well, the viewer is a patient teacher that never gets tired of showing you the same throw.","Slow it down first. The progression ladder on each movement starts with slow and partial versions, then hands-only, then the full movement on the beat. Half speed keeps the timing relationships intact while giving your eyes time to follow.","Mirror the figure if you learn better facing a teacher, and change the camera when one view hides something. Side views show staff tilt and throw drift; top views show hoop planes and helicopter paths. The trails draw where each prop has been, which turns a blur into a shape you can study. The ghost shows where the prop will be on the next beat.","Watch the common mistakes. Each movement can show its typical faults, such as drifting forward, uneven heights or rushing, played deliberately wrong on the figure, with the cue that fixes them. Recognising a fault on the model makes it much easier to feel it in your own body.","Camera mode gives feedback on you. With permission, it tracks your hands and body while you practise and compares your timing with the beat. Processing happens on your device. It is not perfect, and good light helps, but even rough feedback about whether you are early or late is valuable.","Finally, close the viewer sometimes. Practise with music only and trust the counts. The goal is a movement you can do without watching anything at all."]},"music-for-flow":{"title":"Finding music that fits","summary":"Measured tempos, half and double time, generated percussion and your own tracks all keep the counts honest.","imageAlt":"3D figure hooping at the chest with arms raised","body":["Music turns practice into flow, but only if the beat in the music is the beat in the counts. A track at 118 BPM under a 120 BPM routine drifts apart within a minute, and you end up fighting the music instead of riding it.","SynthFlow’s bundled tracks have measured tempos and downbeats, so the player can start each step on the music’s “one” and keep the counts aligned. The builder lists tracks that fit a section’s tempo first, including tracks at half or double the tempo: a 140 BPM track carries a 70 BPM hoop step perfectly well.","Generated percussion works at any tempo. Choose a kit for a section and the player synthesises a beat that matches exactly, whether you are doing a tempo ladder or a slow drill. It is also the best option when you want the pulse without melody pulling your attention.","You can analyse tracks from your own device. The app estimates the tempo and downbeat and lets you check them by tapping along. Tracks with a steady electronic or acoustic pulse work best; music with tempo changes, rubato or long intros is harder to measure and harder to practise to.","Video streaming is turned off during counted practice because its timing cannot be controlled precisely. Use it for warm-ups or free play instead, where nothing needs to line up."]},"plateaus":{"title":"Plateaus and the long middle","summary":"Every flow artist hits weeks where nothing improves; change the drill, the tempo or the prop before changing the goal.","imageAlt":"3D figure juggling Mills Mess with arms crossing","body":["The beginning of flow is wonderful: something new every session. Then, often around the time you can juggle a steady cascade or keep a hoop up indefinitely, progress seems to stop. This long middle is where most people quit, and where the most interesting learning happens.","Plateaus are usually consolidation. Your nervous system is reorganising the movement so it needs less attention, which does not show up as new tricks. Often a skill that felt stuck for two weeks suddenly appears one morning. Keep practising through the flat part.","Change the drill, not the goal. If the cascade will not get faster, practise it at a lower tempo with perfect peaks, then with your eyes on a point above the pattern, then with one hand only. If a staff move will not come, split it into its halves and drill each to the beat. New drills give your brain new information about the same skill.","Cross-train. Learning a second prop often unlocks the first. Hooping improves the rhythm behind juggling; staff work teaches the planes that make hoop tricks clean. The Rewards tree for each art is independent, so variety never costs progress.","Be kind about it. Compare yourself with last month, not with performers online who have practised for ten years. The Progress page keeps an honest record of minutes, top tempos and mastered movements. On a flat week, look at it and see how far the line has already climbed."]},"history-of-juggling":{"title":"A short history of juggling","summary":"From an Egyptian tomb painting to medieval jongleurs, variety theatre and modern mathematics.","imageAlt":"3D figure juggling a three-ball shower in a circle","body":["Juggling is very old. One of the earliest known images is a wall painting in a Middle Kingdom tomb at Beni Hasan in Egypt, roughly four thousand years old, showing women tossing balls. Accounts and images from China, Greece, Rome and the Pacific suggest that people in many cultures found their way to throwing and catching for display and play.","In medieval Europe the word jongleur, from which “juggler” comes, described travelling entertainers who sang, told stories, performed acrobatics and threw objects. Juggling was one skill among many, part of a performer’s toolkit rather than an art of its own.","The variety theatres and circuses of the nineteenth and early twentieth centuries made juggling a headline act. Performers specialised: gentleman jugglers with hats and canes, club jugglers, and numbers jugglers pushing toward seven, eight and more balls. Enrico Rastelli, in the early twentieth century, is still often named as one of the greatest.","From the 1970s a hobby juggling culture grew around clubs, festivals and conventions, with people sharing tricks freely. Mathematics joined in during the 1980s when siteswap notation gave jugglers a way to write patterns as numbers, leading to new tricks discovered on paper before anyone threw them.","Today juggling sits at the meeting point of circus, sport, dance and maths. Some jugglers compete on numbers and endurance, others perform choreography to music, others explore patterns for their own sake. Every route starts with the same exchange of two balls, which you can learn this week."]},"history-of-staff":{"title":"Staff spinning: from weapon to flow","summary":"Martial arts staffs, baton twirling and fire performance all fed the modern spin staff.","imageAlt":"3D figure performing a staff butterfly behind the shoulders","body":["A staff is one of the oldest tools there is, and spinning one is an old skill. Many martial traditions train with a long staff, among them the Okinawan bō, the Chinese gun and European quarterstaff fighting, and their drills include fast spins and hand changes for both defence and display.","Performance spinning has other roots too. Baton twirling grew into a competitive discipline in the twentieth century, with throws, rolls and spins that spinners still borrow. Theatre, parades and street performance across the world used twirled sticks and poles long before anyone called it flow.","The modern flow staff scene grew from the late twentieth century alongside fire performance and festival culture. Fire staffs, with wicks at each end, made spinning visible in the dark and pushed the art toward smooth, continuous movement rather than strikes. LED staffs later brought the same visuals indoors.","Around the same time, flow artists began describing spinning with shared theory: planes, spin and antispin, isolations, timing and direction. Much of it was developed in the poi community and carried across to staff, hoop and other props, which is why the same words appear throughout this app.","Contact staff, where the staff rolls over the body instead of being gripped, developed into its own style with rolls across the neck, shoulders and arms. Today staff spinning ranges from martial demonstration to slow, meditative contact flow, all built on the same first wheel spin."]},"history-of-hoop":{"title":"The hoop: from ancient toy to flow art","summary":"Hoops have been toys and tools for millennia; a 1950s craze and a festival revival made hoop dance an art.","imageAlt":"3D figure walking a spinning hoop up the body","body":["Hoops are among the oldest toys. Children in ancient Egypt, Greece and Rome are described or depicted rolling hoops with sticks and spinning them around the body, and hoop games appear in many cultures since.","Hoops also carry deep cultural meaning in some traditions. The Hoop Dance performed in many Native American communities uses multiple hoops to build shapes such as animals and the earth, telling stories through movement. It is a living tradition in its own right, distinct from the modern flow scene, and worth learning about from its own practitioners.","The plastic hula hoop craze of the late 1950s, driven by mass-produced hoops in the United States, put a hoop in millions of homes almost overnight. For decades afterwards the hoop was mostly seen as a children’s toy and a fitness gadget.","From the late 1990s and 2000s, adult hoopers at festivals and in online communities began treating the hoop as a dance partner. Larger, heavier hand-made hoops made on-body hooping easier for adults, while smaller hoops opened fast off-body tricks. Shared videos spread vocabulary like isolations, wedgies and escalators far beyond any one city.","Modern hoop dance borrows theory from staff and poi and rhythm from every kind of music. It is accessible, joyful and deep: a beginner can find the waist rhythm in a day, and an expert can spend years refining a single isolation."]},"fire-and-led":{"title":"Fire, LED and performance props","summary":"Performance props change weight, speed and risk; learn every move with practice props first and train fire separately.","imageAlt":"3D figure circling a hoop flat overhead like a lasso","body":["Watching a fire staff or an LED hoop at night is often what draws people into flow. Performance props are wonderful, but they are not the same as practice props, and moving to them deserves a plan.","LED props are usually heavier than their practice versions because of batteries and electronics. That changes momentum: spins carry further, throws feel different, and wrists work harder. Learn every movement with your practice prop first, then expect a short adjustment period on LED. Lower the tempo for the first sessions.","Fire performance is a separate discipline. Fuel handling, safe spinning areas, safety spotters with fire blankets, suitable clothing and local rules all matter, and they are best learned in person from experienced fire performers. SynthFlow does not teach fire, and nothing in the app should be practised with lit props.","A good rule used in many flow communities is to only perform a move with a performance prop once you can do it reliably, many times in a row, with a practice prop. Under lights or flames there is no room for experiments.","Performance also changes how you sequence. Audiences read big planes, clean transitions and clear moments of stillness. Build performance routines in the builder like any other, preview them, and rehearse to the same music each time so the counts become choreography."]}}`),a=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"The day the cascade clicked","summary":"Three weeks of chasing balls across the floor ended the moment I stopped watching my hands and started counting.","body":["For three weeks my three-ball cascade lasted exactly four throws. Right, left, right, and then the third ball was somewhere behind the sofa. I watched videos, I slowed down, I sped up. I stood in front of the bed like every tutorial says. Nothing changed, except my vocabulary.","The fix, when it came, was embarrassingly simple. I put on a 90 BPM track and said the counts out loud: one, two, three, four, a throw on every beat. Suddenly the throws had somewhere to be. Instead of throwing when the hand felt ready, which meant whenever panic told it to, each throw waited for its beat. The pattern got slower, higher and calmer.","The second fix was where I looked. I had been staring at my hands, which is like reading a book by watching your eyelids. When I lifted my gaze to the peaks, the two points at the top of the arcs, my hands started catching on their own. The peaks told me whether the throws were even; the hands did not need supervision.","Twelve throws became twenty, then fifty. One evening I juggled through a whole eight-bar step without a drop and grinned at the ceiling like an idiot. The app called it a clean run. I called it the first time juggling felt like music instead of a fight.","If you are stuck at four throws, try what worked for me: count aloud, throw on the beat, look at the peaks. And drop without drama. The floor is where every cascade starts."]},"why-we-count-in-bars":{"title":"Why we count in bars, not seconds","summary":"A forty-second hold makes sense for a stretch; a juggling pattern lives on a beat, so we measure practice in bars.","body":["When we started building SynthFlow, the first big decision was how to measure a routine step. Our sister app SynthYoga counts holds in seconds and breaths. That works for a pose you hold. It does not work for a pattern that repeats on a beat.","A juggling throw, a staff half turn and a hoop orbit are all cycles. If the music runs at 100 BPM and your cascade runs at 103, you are not juggling to the music; you are juggling near it, and within a minute you are a beat behind. Measuring steps in bars at a tempo means the music, the counts, the 3D figure and the next step all start on the same downbeat.","Bars also make progress concrete. “Juggle for a minute” is vague: a minute of what, at what speed? “Eight bars of cascade at 96 BPM” is a specific, repeatable challenge. If you manage it cleanly, the next session can ask for 104. That is how tempo ladders work, and why mastery in the app depends on clean runs rather than just time.","It took serious engineering. Every animation is driven by the same audio clock as the music, scheduled ahead so nothing stutters. Bundled tracks have measured tempos and downbeats. Generated percussion fills any tempo you choose. Tracks from your device get analysed and checked with a tap test. Streaming video is turned off in counted practice because we cannot keep it on the beat.","The result is that the beat becomes a teacher. When you drift, you hear it. When you lock in, you feel it. Counting in bars turned out to be the most important design choice we made."]},"staff-hit-me-in-the-head":{"title":"The staff hit me in the head (and other lessons)","summary":"Every staff spinner gets bonked; padding, planes and patience turn the bonks into progress.","body":["My first figure-8 ended with the staff bouncing off my skull and the dog leaving the room. My second ended the same way, minus the dog. If you are learning staff, you will get hit. The question is how hard, and what you learn from it.","Lesson one: padding is not cowardice. A practice staff with soft ends turned bonks from yelps into shrugs. Shrugging matters, because fear makes you flinch, and a flinching wrist pulls the staff out of its plane, which causes the next bonk.","Lesson two: most hits come from tilted planes. When I filmed myself from the side, I could see the staff leaning toward my face at the top of every turn. My wrists were rolling inward. The plane overlay in the 3D viewer showed the clean version: the staff in a flat sheet beside the body, never leaning in. Fixing the wrist fixed the bonks.","Lesson three: slow and counted beats fast and hopeful. I dropped the tempo to the bottom of the figure-8’s range and counted “right side, left side” with the music. At that speed I could feel the hand change and keep the plane flat. A week later I could go back up.","Lesson four: laugh. Staff spinning is ridiculous and wonderful. The bonks are part of the story everyone in the scene shares. Wear a hat if you need to, clear the ceiling lights, and keep spinning."]},"hooping-for-people-who-cant-hoop":{"title":"Hooping for people who think they can’t hoop","summary":"Most adults who “can’t hoop” were given a toy-sized hoop; a bigger hoop and a forward-and-back pulse fix most of it.","body":["“I can’t hoop” is something hoop teachers hear constantly, usually from someone who last tried with a child’s toy hoop. Small, light hoops spin fast and fall fast. They demand quick, frantic hips. Adults with an adult-sized hoop often find it far more manageable.","Start big. A hoop that reaches roughly between your waist and chest when stood on the floor turns slowly enough for you to feel the rhythm. Heavier hoops also carry more momentum. You can go smaller later for speed and off-body tricks.","Pulse, don’t circle. The most common mistake is trying to make big circles with the hips. Waist hooping is usually a small forward-and-back rock, or a side-to-side one, in time with the hoop. One foot slightly forward helps. The hoop touches your front and back; you push gently as it comes round.","Count it. A relaxed tempo, one orbit per beat, gives your body a rhythm to settle into. The app starts waist hooping slow, then lets you climb. If the hoop sinks, add a little speed to your pulse, not a bigger movement.","Expect it to fall a lot for a few sessions, then suddenly not fall. Hooping is one of those skills that clicks. Once it does, there is a whole world of on-body and off-body flow waiting, and plenty of it does not even need the waist."]},"unlocking-is-not-a-race":{"title":"Unlocking is not a race","summary":"The rewards tree opens harder movements as you master their foundations; the point is the foundations.","body":["SynthFlow’s rewards are movements. Master the cascade and the reverse cascade opens; master the front spin and the figure-8 appears. It is satisfying to watch the tree light up, and we designed it to be. But there is a trap in any unlock system, and it is worth naming.","The trap is treating mastery as a box to tick. You can technically log the clean runs for a movement on a good day, unlock the next one, and move on with a foundation that only works when everything goes right. Then the harder movements feel impossible, because they assume the foundation works when things go wrong.","Mastery in flow means the movement survives distraction: a bit of fatigue, a different tempo, someone walking past. That is why mastery asks for clean runs across sessions, not just in one. And it is why we suggest going back to mastered movements regularly. The cascade is not a level you finish; it is the ground the whole juggling tree stands on.","Locked movements still have pages. You can read about them, watch them in 3D and see what they need. Looking ahead is motivating. Practising ahead, without the foundations, is mostly frustrating.","So enjoy the unlocks, but measure yourself by how easy your oldest movements feel. When the cascade is boring, you are ready for Mills Mess. When Mills Mess is boring, the tree has more to offer."]},"practice-in-ten-minutes":{"title":"A real practice in ten minutes","summary":"Warm-up, one focus movement, one link, a short tempo climb and a cool-down: ten minutes, every day.","body":["The most common reason people give for not practising is time. The truth is that flow skills respond brilliantly to short, frequent sessions. Here is the ten-minute shape we use ourselves.","Minute one to two: warm-up. Wrist circles, arm circles, shoulder rolls, a few hip circles if you hoop. Counted, at a relaxed tempo, so your timing wakes up with your joints.","Minute three to five: your focus movement. One movement you are working on, at a tempo you can do cleanly. Several short counted steps rather than one long one, with a breath between them.","Minute six to seven: one link. Pair the focus movement with something it flows into or out of. Cascade to reverse cascade. Front spin to figure-8. Waist to chest. Links are what make practice feel like flow instead of drills.","Minute eight to nine: a small tempo climb. Two or three rungs, a few BPM each, stopping before form breaks. End on a clean rung.","Minute ten: cool-down. A slow, easy movement or a short rest. Log your effort. Done.","Ten minutes a day is over an hour a week of focused practice, spread in the way coordination likes best. The practice wizard builds sessions of this size when you tell it you are short on time, and the built-in short routines follow the same shape."]},"antispin-broke-my-brain":{"title":"Antispin broke my brain (for a week)","summary":"Turning the staff against the hand’s circle feels impossible until the counts give each petal a beat.","body":["Antispin is where staff spinning starts to feel like geometry homework. Your hand draws a circle one way while the staff turns the other way, and the ends trace a flower. The first time I tried, I produced something more like a wilted dandelion.","What helped was making the shape countable. A four-petal antispin has four moments where an end points straight out from the circle. I gave each one a beat: top, side, bottom, side. Then I slowed the music well below my normal spinning tempo and simply aimed for the positions on the beats.","The ghost in the 3D viewer, which shows where the staff should be on the next beat, was my best friend that week. So was the trail, which drew my flower so I could see when the petals were uneven. Usually the bottom petal was squashed, because I was rushing the bottom of the circle.","After about a week, something shifted. I stopped thinking about the hand and the staff as two things and started feeling the flower as one shape. The tempo came back up on its own.","If antispin is breaking your brain, it is supposed to. Give each petal a beat, slow the music, and let your body work it out. It is one of the best feelings in flow when it does."]},"siteswaps-for-the-maths-shy":{"title":"Siteswaps for the maths-shy","summary":"You do not need to like maths to use siteswap; you only need to know that bigger numbers go higher.","body":["Siteswap notation has a reputation for scaring people off. Jugglers will cheerfully say “try 531” as if it explained something. It does, but only once you know a couple of things, and those things are simpler than they look.","Here is nearly everything you need. Each number is a throw. Bigger numbers go higher. Odd numbers cross to the other hand; even numbers come back to the same hand. A 3 is a normal cascade throw. A 1 is a quick zip across. A 2 is usually just holding the ball.","That is enough to read 441: two higher throws that stay on their own side, then a zip across. You can now try it without reading another word. Throw, throw, zip, on the beat.","If you want one more piece: add the numbers and divide by how many there are, and you get the number of balls. 4 + 4 + 1 = 9, divided by 3 is 3 balls. If the answer is not a whole number, the pattern cannot be juggled. That is the whole of the famous average theorem.","In SynthFlow, every juggling movement has a siteswap, and the 3D engine animates directly from it. That means the figure always throws exactly the heights the numbers describe, on the exact beats. Watching a siteswap animated slowly is the fastest way we know to make the numbers make sense. No maths degree required."]},"music-that-fights-you":{"title":"When the music fights you","summary":"A track that drifts against the counts makes every movement harder; measured tempos and generated beats fix it.","body":["You have probably felt it: a song you love, a movement you know, and somehow everything feels wrong. You rush, you drop, you blame yourself. Often the problem is not you. It is that the song’s tempo does not match the movement.","Every flow movement has a comfortable tempo range. Below it, spinning props stall; above it, throws get low and frantic. A track at 128 BPM under a hoop movement that likes 90 asks you to choose between the music and the hoop. The good news is that half time and double time help: 128 can carry a movement at 64, one cycle every two beats.","Drift is the subtler problem. If the music says 120 but the counts say 116, the two slide apart over a minute, and your body cannot follow both. This is why SynthFlow uses measured tempos for its bundled tracks, generates percussion at any exact tempo, and checks tracks from your device with a tap test.","When a track fights you, do not fight back. Switch to the generated beat for the step, or let the builder suggest a track in the right range. Keep the songs you love for free play, where nothing needs to line up.","Music should feel like a partner. If it feels like an opponent, change the music, not your movement."]},"learning-alongside-my-kid":{"title":"Learning to juggle alongside my kid","summary":"Two beginners, one bag of balls and a rule: we celebrate drops as loudly as catches.","body":["My daughter asked to learn juggling, and I realised I could not juggle either. So we learned together, ten minutes after dinner, with three beanbags each and one rule: we cheer drops as loudly as catches.","The rule sounds silly. It turned out to be the most important part. Kids, and adults, tense up when they think a mistake is embarrassing. Tension makes throws worse. Cheering every drop turned the floor into part of the game and kept both of us loose.","We started with one ball, tossing it from hand to hand to the beat, eye-level peaks. It felt too easy for about three sessions and then suddenly important, because two-ball exchanges only work if those single throws are consistent. She got the exchange before I did and was unbearable about it.","The counted music helped us practise together. Same tempo, same downbeat, two people throwing in time. When one of us lost the pattern, the other kept going, and the dropper came back in on the next “one”.","Four weeks in, we both have a wobbly cascade. More importantly, we have a habit we both look forward to. If you have a kid who wants to learn something, learn it with them. Being a beginner together is underrated."]},"why-your-throws-drift-forward":{"title":"Why your throws drift forward","summary":"If you finish every cascade three steps from where you started, your throws are leaning away from you. Here is how to bring them home.","body":["Every juggler knows the walk. You start the cascade in the middle of the room and finish it with your nose against the wall, chasing the pattern one step at a time. It feels like the balls are pulling you. They are not. You are throwing them forward, a few centimetres at a time, and then walking to catch up.","The cause is almost always the elbows. When you get tense, the forearms tip forward and the hands release the ball slightly ahead of the body. Each throw lands a little further out, so the next catch happens further out, so the next throw starts further out. It compounds quickly.","The fix I teach first is the elbow tuck. Keep the elbows near the ribs, forearms roughly level, and throw the balls straight up past your eyes rather than out in front of them. It feels cramped for a day. Then it feels calm.","The second fix is a wall. Stand facing it, about a forearm away, and juggle. If the throws drift, the wall tells you immediately, and loudly. Ten minutes of wall practice teaches the body what an upright pattern feels like faster than anything I can say.","SynthFlow’s camera mode watches for drift too. It tracks how much bigger your torso looks to the camera over a step, which means you are walking towards it, and nudges you with a short cue. The 3D coach can also show the ghost of a forward throw beside the clean one, so you can see the difference rather than just hear about it.","Drift is not a character flaw. It is a tension habit, and habits change with repetition. Tuck the elbows, throw up not out, and let the wall keep you honest."]},"practising-to-a-click":{"title":"Practising to a click","summary":"A metronome sounds like the least fun thing in the world. It turned out to be the thing that made my flow feel like dancing.","body":["I resisted the click for years. Music was the point of flow arts for me, and a metronome felt like homework. Then a friend who plays drums watched me juggle and said, kindly, that I sped up every time I got excited and slowed down every time I got scared. She was right, and I had no idea.","So I tried a week of practice to nothing but a click. The first discovery was that a steady pulse is harder than it sounds. My two-in-one-hand pattern wanted to rush. My staff figure-8 wanted to drag on the weak side. The click did not care how I felt; it just kept time.","The second discovery was that the click made music easier. After a week, when I put real tracks back on, I could feel where the beat sat inside the sound. I stopped fighting songs with loose timing and started choosing which part of the groove to lock onto.","SynthFlow’s generated percussion is a friendlier version of the click. You choose a kit, from a plain click to hand drums, and it plays at any tempo, so a pattern can live at exactly the speed you can hold. It can also run quietly under a music track as a guide. I still use it alone for the first few minutes of every session.","If you want to try this, pick one pattern and one tempo that feels slightly too slow. Count out loud for four bars, then stop counting and just listen. When the pattern and the click feel like one sound, add four BPM. That is the whole method."]},"staff-in-a-small-apartment":{"title":"Staff in a small apartment","summary":"A 1.4 metre staff and a 2.4 metre ceiling can live together. You just have to pick your planes.","body":["My flat has low ceilings, a light fitting I am fond of, and a downstairs neighbour who works nights. None of that is ideal for staff spinning. I practised in parks for a year before I worked out that most of my training could happen indoors after all.","The trick is planes. Wheel-plane spins, the big ones beside the body, need the full height of the staff above your head. Wall-plane work in front of the body needs width but less height. Floor-plane spins, like the helicopter, need clearance above your head but nothing around your shins. Each room supports different moves.","In my living room I can do isolations, front spins and slow figure-8s with my arms low. In the hallway I can do nothing at all, so the hallway is for wrist warm-ups. The bedroom has the highest ceiling, so wheel-plane work happens there, slowly, with the light fitting removed and stored in a drawer.","Short staffs help too. A practice staff that is a hand’s length shorter than my performance staff turned a lot of near misses into easy clearance. The timing changes a little, so I check my full-length staff outside once a week.","For the neighbours: practice mats and soft-ended staffs. A drop onto a yoga mat is a dull thud instead of a crack. I also keep indoor sessions to counted routines of ten minutes, which keeps the noise short and the practice focused.","SynthFlow lets you mark movements you cannot do at home as disliked so the generator leaves them out of indoor routines. Small spaces do not stop progress. They just make you very good at isolations."]},"hooping-after-40":{"title":"Hooping after 40","summary":"I picked up a hoop for the first time at 43. My back, my knees and my pride all had opinions. Here is what worked.","body":["I bought my first adult hoop on a whim after a festival, convinced I would be terrible. I was terrible. I was also, within a month, hooping on my waist for whole songs, and within six months doing simple off-body moves. Age did not stop me. It just changed how I needed to practise.","The big lesson was to warm up properly. Hip circles, torso twists and gentle knee bounces take three minutes and make the first hoop of the session feel smooth instead of creaky. SynthFlow puts warm-ups at the start of every routine for a reason, and I stopped skipping them after one stiff morning.","The second lesson was hoop size. A bigger, slightly heavier hoop turns more slowly, which gives you more time and asks less effort from the lower back. I started with a hoop that reached between my waist and chest when stood on the floor, and I still use it for long practice sessions.","Third: pulse, do not circle. Beginners often swing the hips in a circle, which twists the spine more than it needs to. A front-and-back pulse, or side-to-side if the hoop turns that way for you, keeps the hoop up with less strain. The 3D coach shows this clearly if you watch the hips rather than the hoop.","Finally, short and often beats long and occasional. Ten minutes four times a week did more for me than an hour on Sunday. My body recovered between sessions, and the moves stuck.","If you are over 40 and curious, start. The hoop does not know how old you are."]},"fire-and-the-beginner":{"title":"Fire and the beginner","summary":"Fire spinning is the most visible part of flow arts and the part beginners ask about most. The honest answer is: not yet, and not alone.","body":["Every week someone asks us when SynthFlow will teach fire. It is a fair question. Fire is beautiful, and plenty of spinners got into the scene after seeing a fire circle at night. But we will never coach anyone to light a prop, and this post explains why.","Fire adds hazards that have nothing to do with skill: fuel handling, clothing, wind, spectators, burns and extinguishing. These are learned from experienced people in person, with a trained safety person present and proper equipment ready. An app cannot check your fuel dump, your cotton clothing or your safety towel.","What the app can do is help you build the skills fire needs before you ever go near it. That means moves you can do reliably for a full song, at a steady tempo, without drops. If a pattern still surprises you at home with a practice prop, it is not ready for fire.","A useful test from the fire community: can you do the routine with your eyes half closed, in the dark, while someone talks to you? Fire is bright, hot and loud, and it takes your attention. Your body has to know the moves without supervision.","LED props are a great step in between. They give you the night-time look, the trails and the audience reaction without the risk. SynthFlow’s LED style pack shows what your patterns will look like lit up, which is also a good way to spot sloppy planes.","When you are ready, find a local fire jam, introduce yourself, and ask to learn safety first. Spin practice props until then. The fire will still be there."]},"four-balls-taught-me-patience":{"title":"Four balls taught me patience","summary":"Moving from three balls to four took me longer than learning three in the first place, and it changed how I think about practice.","body":["Three balls took me five weeks. Four took me five months. Nobody warned me about this, so I am warning you: four balls is not three balls plus one. It is a completely different pattern, and your body has to learn it from scratch.","In a four-ball fountain, each hand juggles two balls on its own, and the balls never cross. The hands usually alternate, but there is no exchange between them at all. Everything I had learned about catching a ball from the other hand was suddenly useless.","So I went back to one hand. Two balls in the right hand, in columns, then circles, until I could do fifty throws without thinking. Then the left hand, which took three times as long. Then both hands together, first in sync, then alternating. The tempo ladder in SynthFlow helped here: I started each week at the bottom of the fountain’s range and only moved up after a clean run.","The patience lesson came from the plateaus. Some weeks nothing improved. I recorded drops and clean runs anyway, and the graph showed slow progress even when it felt like none. The data made the boring weeks bearable.","The other lesson was about rest. Four balls tired my forearms in a way three never did. When I practised every day, I got worse. When I practised every other day, I got better. Grip muscles need recovery like any others.","If you are stuck between three and four, split the problem, trust the slow weeks, and give your forearms a day off. It does arrive."]},"the-escalator-and-hand-traffic":{"title":"The escalator and the art of hand traffic","summary":"Hoop hand moves look like magic until you see that they are just careful traffic management between two hands.","body":["The first time I saw an escalator, the hoop seemed to climb up the hooper’s arms and float down again, endlessly, with no obvious grip. I assumed it needed years of practice. It needed about three weeks, once I understood that it is just a pattern of handoffs.","Almost every off-body hoop move is about which hand holds the hoop, when it lets go, and where the other hand meets it. If the timing between the hands is fuzzy, the hoop wobbles out of its plane and the move falls apart. If the timing is clean, the hoop looks like it is moving by itself.","So I started naming handoffs. Over SynthFlow’s count I said the hands out loud instead of the numbers: right, left, right, left, one on each beat. Saying them with the music forced me to notice when my left hand grabbed early. Early grabs were the source of almost every wobble.","The second key was keeping the hoop in its plane. A hand that twists as it grips tilts the hoop, and a tilted hoop is a dropped hoop half a second later. The plane overlay helps here, and so does practising in front of a mirror with slow tempos.","Once the escalator felt reliable, other hand moves came faster. Isolations, passes and lassos all use the same idea: clear handoffs, flat planes, steady timing. The magic is just traffic management."]},"behind-the-back-without-fear":{"title":"Behind the back without fear","summary":"Staff behind-the-back passes are where most spinners stall. The problem is usually not skill but the urge to look.","body":["For months my behind-the-back pass was a front pass with a hopeful twist. I would start the move, panic as the staff left my view, and bring it back in front of me. The staff never actually went behind my back. My brain would not let it.","The breakthrough came from accepting that I could not see the move. You cannot watch a behind-the-back pass. You have to feel where the staff is from the hand that is letting go and trust the hand that is waiting.","I trained that feeling in slow motion. Without spinning at all, I passed the staff behind my back, hand to hand, with my eyes forward. Then with a slow half turn first. Then at the bottom of the move’s tempo range, counted. Every step felt silly. Every step worked.","The 3D coach was surprisingly useful because I could rotate the view and watch the move from behind. Seeing where the hands meet, and how the staff stays in the wall plane as it goes round, gave my body a map it could not get from the front.","The second fear was hitting myself. A soft-ended practice staff and a big clear space solved that. Once I knew a mistake would cost a gentle bump rather than a bruise, I stopped flinching, and the flinch had been causing the misses.","If behind the back still scares you, slow it right down, take the spin out, and keep your eyes forward. Your hands know more than you think."]},"why-reverse-feels-wrong":{"title":"Why the reverse cascade feels wrong","summary":"The reverse cascade uses the same hands, the same balls and the same rhythm as the cascade. So why does it feel like starting again?","body":["When I learned the reverse cascade, I expected it to take an afternoon. It is the same three balls, the same alternating hands and the same tempo as the cascade. It took three weeks, and I could not work out why.","The answer is direction. In a normal cascade, each ball is thrown from the inside of the pattern and caught on the outside. In a reverse cascade, the ball is thrown from the outside, over the top of the incoming ball, and caught on the inside. Your hands are making the same rhythm but completely different shapes.","The new shape breaks your timing. In the cascade, you throw just as the incoming ball starts to fall. In the reverse, you need to throw a little earlier so your ball clears the top of the other one. Throw at the old moment and the balls collide.","I fixed it with two balls first. Two balls, reverse direction, counted on the beat, until it felt automatic. Then three balls at a slow tempo with the counts said aloud. SynthFlow’s ghost overlay showed me a typical mistake, a throw that is too low and clips the other ball, and I could see I was doing exactly that.","Once it clicked, it unlocked a lot. Mixing cascade and reverse is the basis of many tricks, and the reverse shape turns up again in Mills Mess. Being bad at it for three weeks was worth it."]},"making-a-prop-stand-still":{"title":"Isolations: making a prop stand still","summary":"An isolation is a move where the prop seems to stay in one place while you move around it. It is the most satisfying illusion in flow arts.","body":["The first time I nailed a staff isolation, my friend asked how the staff was floating. It was not floating, of course. My hands were moving in a careful circle so that one point on the staff stayed fixed in the air. But from the outside it looked impossible, and that feeling is why I love isolations.","Every isolation works the same way. Choose a point on the prop, usually the centre or one end, and keep that point still while the rest of the prop turns. Your hands have to move in exactly the opposite way to how the prop wants to move. It is counterintuitive and slightly hypnotic.","The hardest part is that your body moves too. Hips shift, shoulders turn, and every small movement shows up as wobble in the fixed point. I practised in front of a mirror with a piece of tape on the glass marking where the fixed point should be. If the prop’s centre left the tape, I knew.","Hoop isolations follow the same idea. In SynthFlow I turn on trails in the 3D viewer and watch the coach: in a clean isolation, the trail around the fixed point stays tiny. When I slowed the tempo right down and copied it, I could feel my hands drifting at the top of each circle.","Isolations also build control that helps everything else. Once you can hold a prop still, you can place it anywhere you choose. Planes get flatter, transitions get cleaner, and your flow starts to look intentional rather than lucky.","Start slow, mark the fixed point, and watch it like a hawk. Then show a friend and enjoy their face."]}}`),o={"zero-to-cascade":{name:`Zero to cascade in 4 weeks`,description:`One ball, then two, then the third joins. A short session a day is enough: finish each week’s routine to master its movement and open the next.`,weeks:[{label:`Week 1 · One ball`},{label:`Week 2 · Two balls`},{label:`Week 3 · The third ball`},{label:`Week 4 · Cascade`}]},"beyond-the-cascade":{name:`Beyond the cascade`,description:`Four weeks of three-ball variety: tennis and claws, then body throws, then sync patterns two balls at a time.`,weeks:[{label:`Week 1 · Tennis and claws`},{label:`Week 2 · Half shower`},{label:`Week 3 · Body throws`},{label:`Week 4 · Columns`}]},"first-clubs":{name:`First clubs`,description:`From a single spinning club to a steady three-club cascade, then doubles for height and spin control.`,weeks:[{label:`Week 1 · One club`},{label:`Week 2 · Exchange`},{label:`Week 3 · Cascade`},{label:`Week 4 · Doubles`}]},"passing-with-a-partner":{name:`Passing with a partner`,description:`Two jugglers, face to face. One ball across, then two each on a shared beat, then the six-count, four-count and two-count with three balls each.`,weeks:[{label:`Week 1 · One ball across`},{label:`Week 2 · Two balls each`},{label:`Week 3 · Six-count and four-count`},{label:`Week 4 · Two-count`}]},"staff-foundations":{name:`Staff foundations`,description:`Wheel and front spins, the figure 8 and the pass-through: the four moves almost every staff flow is built from.`,weeks:[{label:`Week 1 · Wheel spin`},{label:`Week 2 · Front spin`},{label:`Week 3 · Figure 8`},{label:`Week 4 · Pass-through`}]},"staff-contact":{name:`Staff contact`,description:`Loosen the grip week by week: steering wheel and fishtail, then hand rolls, then the staff turning on the forearm.`,weeks:[{label:`Week 1 · Steering wheel`},{label:`Week 2 · Fishtail`},{label:`Week 3 · Hand roll`},{label:`Week 4 · Forearm roll`}]},"double-staff-start":{name:`Double staff start`,description:`From two staffs in step to split time and wheels on both sides.`,weeks:[{label:`Week 1 · Same time`},{label:`Week 2 · Split time`},{label:`Week 3 · Wheels`},{label:`Week 4 · Split wheels`}]},"hoop-body-ladder":{name:`Hoop body ladder`,description:`Waist hooping both ways, then down to the hips and thighs and up to the chest.`,weeks:[{label:`Week 1 · Both directions`},{label:`Week 2 · Hips`},{label:`Week 3 · Thighs`},{label:`Week 4 · Chest lift`}]},"hoop-doubles-start":{name:`Hoop doubles start`,description:`A hoop in each hand: mirrored spins, offset spins, side spins, then one on the waist and one in the hand.`,weeks:[{label:`Week 1 · Mirrored spins`},{label:`Week 2 · Offset spins`},{label:`Week 3 · Side spins`},{label:`Week 4 · Waist and hand`}]},"off-body-hoop":{name:`Off-body hoop`,description:`From spinning the hoop on one hand to lassos, passes, wedgies and the isolation that makes the hoop seem to float.`,weeks:[{label:`Week 1 · Hand spin`},{label:`Week 2 · Lasso and pass`},{label:`Week 3 · Wedgie`},{label:`Week 4 · Isolation`}]},"first-poi":{name:`First poi`,description:`One poi, then a pair: wall spins both ways, wheels at your sides, then split time.`,weeks:[{label:`Week 1 · One poi`},{label:`Week 2 · Wall spins`},{label:`Week 3 · Wheels`},{label:`Week 4 · Split time`}]},"poi-weave-ladder":{name:`Poi weave ladder`,description:`From chase the sun to the three-beat weave in both directions, then the quicker two-beat weave.`,weeks:[{label:`Week 1 · Chase the sun`},{label:`Week 2 · Three-beat weave`},{label:`Week 3 · Reverse weave`},{label:`Week 4 · Two-beat weave`}]},"poi-antispin-start":{name:`Antispin start`,description:`Extensions and isolations first, then antispin with one poi and the four-petal flower with two.`,weeks:[{label:`Week 1 · Extensions`},{label:`Week 2 · Isolation`},{label:`Week 3 · One-poi antispin`},{label:`Week 4 · Antispin flower`}]}},s={"sf-ambient-70":{name:`Slow Orbit`},"sf-world-75":{name:`Market Steps`},"sf-ambient-80":{name:`Lantern Drift`},"sf-world-85":{name:`Desert Wheel`},"sf-handdrum-90":{name:`Circle Drum`},"sf-funk-95":{name:`Loose Wrists`},"sf-handdrum-100":{name:`Firelight Hands`},"sf-world-105":{name:`River Bells`},"sf-funk-110":{name:`Pocket Cascade`},"sf-handdrum-115":{name:`Courtyard Groove`},"sf-electronic-120":{name:`Neon Staff`},"sf-funk-125":{name:`Bounce Pattern`},"sf-electronic-130":{name:`Pixel Hoop`},"sf-handdrum-135":{name:`Sunset Djembe`},"sf-electronic-140":{name:`LED Trails`},"sf-funk-145":{name:`Spin Cycle`},"sf-electronic-150":{name:`Strobe Flow`},"sf-handdrum-155":{name:`Fast Palms`},"sf-electronic-160":{name:`Night Spinner`}},c={poses:n,routines:r,learn:i,blog:a,progressions:o,music:s};export{t as n,c as t};